import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";
import type { IPageDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardCommentSnapshot";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and filtering comment snapshots (version histories) in discussionboard_comment_snapshots.
 *
 * This test covers the full spectrum of supported filters and pagination for the comment snapshot audit/history API:
 * - Creation of multiple comments and snapshot versions across two members and two posts
 * - Filters: by comment ID, member ID, post ID, version, snapshot_created_at (range)
 * - Pagination parameters and boundary (limit/page/out-of-bounds) handling
 * - Validation that only schema fields are returned
 * - Negative test for errors with unsupported filter properties
 *
 * Test Steps:
 * 1. Create two unique member IDs and two post IDs
 * 2. Create three comments: two in post1 (with two authors), one in post2
 * 3. For each comment, generate 3 snapshot version records, alternating editors (members)
 * 4. List all snapshots (no filters), seeing at least all test-created records
 * 5. Filter by comment ID and assert all results match
 * 6. Filter by member ID and assert all results match
 * 7. Filter by post ID and assert all results match
 * 8. Filter by version, assert only matching records returned
 * 9. Filter by snapshot_created_at range (from/to) and assert correctness
 * 10. Pagination: test with limit=2, get multiple pages
 * 11. Out-of-bounds page returns zero results
 * 12. Assert only schema fields present in responses
 * 13. Error on unsupported filter property
 */
export async function test_api_discussionboard_test_list_comment_snapshots_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two member IDs, two post IDs for realistic cross-combos
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const postId1 = typia.random<string & tags.Format<"uuid">>();
  const postId2 = typia.random<string & tags.Format<"uuid">>();

  // 2. Create three comments (c1 in post1/member1, c2 in post1/member2, c3 in post2/member1)
  const comment1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId1,
        discussionboard_member_id: memberId1,
        body: "Alpha comment",
      } satisfies IComment.ICreate,
    },
  );
  typia.assert(comment1);
  const comment2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId1,
        discussionboard_member_id: memberId2,
        body: "Beta comment",
      } satisfies IComment.ICreate,
    },
  );
  typia.assert(comment2);
  const comment3 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postId2,
        discussionboard_member_id: memberId1,
        body: "Gamma comment",
      } satisfies IComment.ICreate,
    },
  );
  typia.assert(comment3);

  // 3. For each comment, create 3 snapshot versions, stagger snapshot_created_at and alternate authors
  const SNAPSHOT_CT = 3;
  const now = new Date();
  function advanceMinutes(date: Date, min: number) { return new Date(date.getTime() + min * 60000); }
  const snapshots: IDiscussionboardCommentSnapshot[] = [];
  for (const [idx, comment] of [
    [0, comment1],
    [1, comment2],
    [2, comment3],
  ] as const) {
    for (let v = 1; v <= SNAPSHOT_CT; ++v) {
      const snap_date = advanceMinutes(now, idx * 10 + v);
      const snap = await api.functional.discussionboard.commentSnapshots.create(
        connection,
        {
          body: {
            discussionboard_comment_id: comment.id,
            discussionboard_member_id: v % 2 === 1 ? memberId1 : memberId2,
            discussionboard_post_id: comment.discussionboard_post_id,
            body: `${comment.body} v${v}`,
            version: v,
            snapshot_created_at: snap_date.toISOString(),
          } satisfies IDiscussionboardCommentSnapshot.ICreate,
        },
      );
      typia.assert(snap);
      snapshots.push(snap);
    }
  }

  // 4. Retrieve snapshots with no filter; expect all test records at minimum
  const all = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: {} },
  );
  typia.assert(all);
  TestValidator.predicate("all records included")(all.data.length >= snapshots.length);

  // 5. Filter by comment ID
  const filteredByComment = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { discussionboard_comment_id: comment1.id } },
  );
  typia.assert(filteredByComment);
  TestValidator.predicate("comment filter")(filteredByComment.data.every(d => d.discussionboard_comment_id === comment1.id));

  // 6. Filter by member ID
  const filteredByMember = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { discussionboard_member_id: memberId1 } },
  );
  typia.assert(filteredByMember);
  TestValidator.predicate("member filter")(filteredByMember.data.every(d => d.discussionboard_member_id === memberId1));

  // 7. Filter by post ID
  const filteredByPost = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { discussionboard_post_id: postId2 } },
  );
  typia.assert(filteredByPost);
  TestValidator.predicate("post filter")(filteredByPost.data.every(d => d.discussionboard_post_id === postId2));

  // 8. Filter by version
  const versionToCheck = 2;
  const filteredByVersion = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { version: versionToCheck } },
  );
  typia.assert(filteredByVersion);
  TestValidator.predicate("version filter")(filteredByVersion.data.every(d => d.version === versionToCheck));

  // 9. Filter by snapshot_created_at range
  const fromDate = advanceMinutes(now, 1).toISOString();
  const toDate = advanceMinutes(now, 15).toISOString();
  const filteredByDate = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    {
      body: {
        snapshot_created_from: fromDate,
        snapshot_created_to: toDate,
      },
    },
  );
  typia.assert(filteredByDate);
  TestValidator.predicate("date filter")(filteredByDate.data.every(d => d.snapshot_created_at >= fromDate && d.snapshot_created_at <= toDate));

  // 10. Pagination: limit = 2, get page 1 & 2
  const page1 = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { limit: 2, page: 1 } },
  );
  typia.assert(page1);
  TestValidator.equals("pagination limit")(page1.data.length)(2);
  const page2 = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { limit: 2, page: 2 } },
  );
  typia.assert(page2);
  TestValidator.predicate("page increment")(page2.pagination.current === 2);

  // 11. Out-of-bounds page: expect zero results
  const totalPages = page1.pagination.pages;
  const pageBeyond = await api.functional.discussionboard.commentSnapshots.index(
    connection,
    { body: { limit: 2, page: totalPages + 10 } },
  );
  typia.assert(pageBeyond);
  TestValidator.equals("out of bounds")(pageBeyond.data.length)(0);

  // 12. Schema field validation: only defined fields allowed
  if (page1.data.length > 0) {
    const allowedFields = [
      "id",
      "discussionboard_comment_id",
      "discussionboard_member_id",
      "discussionboard_post_id",
      "body",
      "version",
      "snapshot_created_at",
    ];
    const sample = page1.data[0];
    for (const k of Object.keys(sample)) {
      TestValidator.predicate(`schema-only fields: ${k}`)(allowedFields.includes(k));
    }
  }

  // 13. Negative: error if unsupported property passed
  await TestValidator.error("unsupported filter error")(async () => {
    await api.functional.discussionboard.commentSnapshots.index(
      connection,
      { body: { not_a_field: "bad" } as any },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
