import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Test updating a discussion board comment snapshot (history record) by id with valid and invalid payloads.
 *
 * This test validates the ability to fully update (PUT) a comment snapshot using proper schema, and checks the reaction to invalid ids and constraint violations.
 * - Confirms updates reflect on the returned record.
 * - Attempts updates with malformed and non-existent ids (expects error).
 * - Attempts updates with constraint-violating or malformed payloads (expects error).
 *
 * Steps:
 * 1. Create a discussionboard member (for authorship).
 * 2. Create a comment authored by that member.
 * 3. Create a comment snapshot for the comment.
 * 4. Update the snapshot by id with a valid payload and verify changes.
 * 5. Attempt to update using malformed/non-existent ids (should error).
 * 6. Attempt updates with invalid payloads (empty body, negative version, bad date format; should error).
 */
export async function test_api_discussionboard_test_update_comment_snapshot_with_valid_and_invalid_payloads(
  connection: api.IConnection,
) {
  // 1. Create a discussionboard member to act as comment/snapshot author
  const memberEmail = typia.random<string & tags.Format<'email'>>();
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: 'member',
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a comment authored by the member
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<'uuid'>>(),
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(3),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment);

  // 3. Create an initial snapshot for the comment
  const origSnapshot = await api.functional.discussionboard.commentSnapshots.create(connection, {
    body: {
      discussionboard_comment_id: comment.id,
      discussionboard_member_id: member.id,
      discussionboard_post_id: comment.discussionboard_post_id,
      body: comment.body,
      version: 1,
      snapshot_created_at: new Date().toISOString(),
    } satisfies IDiscussionboardCommentSnapshot.ICreate,
  });
  typia.assert(origSnapshot);

  // 4. Successfully update the snapshot with valid new values
  const newBody = RandomGenerator.paragraph()(2);
  const newVersion = origSnapshot.version + 1;
  const newSnapshotCreatedAt = new Date(Date.now() + 60000).toISOString();
  const updated = await api.functional.discussionboard.commentSnapshots.update(connection, {
    id: origSnapshot.id,
    body: {
      body: newBody,
      version: newVersion,
      snapshot_created_at: newSnapshotCreatedAt,
    } satisfies IDiscussionboardCommentSnapshot.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals('body updated')(updated.body)(newBody);
  TestValidator.equals('version updated')(updated.version)(newVersion);
  TestValidator.equals('snapshot_created_at updated')(updated.snapshot_created_at)(newSnapshotCreatedAt);

  // 5. Negative test: update with malformed id
  await TestValidator.error('malformed id')(() =>
    api.functional.discussionboard.commentSnapshots.update(connection, {
      id: 'not-a-uuid' as any,
      body: {
        body: RandomGenerator.paragraph()(1),
        version: 99,
        snapshot_created_at: new Date().toISOString(),
      },
    })
  );

  // 6. Negative test: update with non-existent id
  await TestValidator.error('non-existent id')(() =>
    api.functional.discussionboard.commentSnapshots.update(connection, {
      id: typia.random<string & tags.Format<'uuid'>>(),
      body: {
        body: RandomGenerator.paragraph()(1),
        version: 100,
        snapshot_created_at: new Date().toISOString(),
      },
    })
  );

  // 7. Negative test: update with empty body
  await TestValidator.error('empty body payload')(() =>
    api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: {
        body: '',
        version: origSnapshot.version + 2,
        snapshot_created_at: new Date().toISOString(),
      },
    })
  );

  // 8. Negative test: update with negative version
  await TestValidator.error('negative version')(() =>
    api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: {
        body: RandomGenerator.paragraph()(1),
        version: -11 as any,
        snapshot_created_at: new Date().toISOString(),
      },
    })
  );

  // 9. Negative test: update with malformed date
  await TestValidator.error('malformed snapshot_created_at')(() =>
    api.functional.discussionboard.commentSnapshots.update(connection, {
      id: origSnapshot.id,
      body: {
        body: RandomGenerator.paragraph()(1),
        version: origSnapshot.version + 3,
        snapshot_created_at: 'invalid-date' as any,
      },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IDiscussionboardCommentSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCommentSnapshot";

/**
 * Permanently deletes a comment snapshot and verifies its removal.
 *
 * Validates the hard-delete operation for comment snapshots:
 * - Ensures deletion is physical with no soft-delete
 * - After deleting, verifies the snapshot cannot be fetched (where possible)
 * - Deletion by invalid id triggers an error
 *
 * The test does:
 * 1. Creates a base comment to anchor the snapshot
 * 2. Creates a comment snapshot linked to the base comment
 * 3. Deletes the snapshot by id using hard-delete endpoint
 * 4. Attempts to fetch the deleted snapshot (simulate unreachable since no GET API)
 * 5. Attempts to delete a snapshot with a non-existent id to confirm error/404
 *
 * Limitations:
 * - There is NO GET endpoint for fetching a comment snapshot by id, so post-deletion retrieval is only simulated by an error expectation.
 *
 * Post-conditions:
 * - The snapshot is irreversibly deleted and cannot be recovered or re-accessed
 * - No soft-delete (no deleted_at or similar)
 */
export async function test_api_discussionboard_test_hard_delete_comment_snapshot_and_verify_removal(connection: api.IConnection) {
  // 1. Create a base comment for linking snapshot
  const comment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
