import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IPageDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 시스템 전체 구성 설정 목록의 검색 및 필터 기능 검증.
 *
 * 관리자(ADMIN)이 discussionboard_configurations 테이블의 레코드를 다양한 검색/필터 조건으로 조회하는 시나리오를 구현합니다. 실제로 존재하는 필드만 IRequest 오브젝트에 사용되어야 하며, 아래 케이스들을 포함합니다.
 *
 * 1. 키워드 검색(q): key 및 description 필드에서 부분일치 찾기.
 * 2. key, value, description으로 개별적으로 필터링.
 * 3. 생성일(created_at), 수정일(updated_at)로 기간 조건 검색.
 * 4. id로 단건(또는 없음) 지정 검색.
 * 5. 페이지네이션(page/limit) 기능 확인. (1페이지, 2페이지 등 실제 데이터 차별화)
 * 6. 각 결과 레코드가 IDiscussionboardConfiguration의 모든 필드(id, key, value, description, created_at, updated_at)를 포함하는지 검증.
 * 7. orderBy 및 orderDirection으로 정렬이 잘 적용되는지 확인.
 *
 * 각 검색/필터/정렬 조건의 조합(AND 방식)이 잘 동작하는지 검증하며, 스키마 외의 필드는 절대 사용하지 않음에 유의.
 */
export async function test_api_discussionboard_test_list_configurations_with_search_and_filter(
  connection: api.IConnection,
) {
  // 1. 설정 데이터가 하나 이상 존재한다고 가정. 실제로는 관리자 권한이 필요할 수 있으니 사전 인증 절차가
  //    필요하다면 별도 적용 필요(현재 시나리오에서는 생략).

  // 2. [키워드 통합 검색(q)] key/description에서 부분일치 찾기
  const keyword = "max";
  const out_keyword = await api.functional.discussionboard.configurations.index(connection, {
    body: {
      q: keyword,
      page: 1,
      limit: 10,
    },
  });
  typia.assert(out_keyword);
  // 모든 결과가 키 또는 설명 중 하나 이상에 keyword가 포함되는지 확인
  for (const item of out_keyword.data) {
    TestValidator.predicate(`keyword-filtered: key|desc match`)(
      item.key.includes(keyword) || (item.description ?? "").includes(keyword),
    );
  }
  // pagination 필드 검증
  typia.assert(out_keyword.pagination);

  // 3. [key, value, description 별도 개별 필터]
  const filterKey = out_keyword.data[0]?.key ?? "max_post_per_hour";
  const filterValue = out_keyword.data[0]?.value ?? "10";
  const filterDesc = out_keyword.data[0]?.description ?? null;

  const out_key = await api.functional.discussionboard.configurations.index(connection, { body: { key: filterKey } });
  typia.assert(out_key);
  for (const item of out_key.data) {
    TestValidator.equals("key match")(item.key)(filterKey);
  }

  const out_value = await api.functional.discussionboard.configurations.index(connection, { body: { value: filterValue } });
  typia.assert(out_value);
  for (const item of out_value.data) {
    TestValidator.equals("value match")(item.value)(filterValue);
  }

  const out_desc = await api.functional.discussionboard.configurations.index(connection, { body: { description: filterDesc } });
  typia.assert(out_desc);
  for (const item of out_desc.data) {
    TestValidator.equals("desc match")(item.description)(filterDesc);
  }

  // 4. [created_at/updated_at] 기간 조건 검색
  if (out_keyword.data.length > 0) {
    const created = out_keyword.data[0].created_at;
    const out_created = await api.functional.discussionboard.configurations.index(connection, {
      body: { created_at: created },
    });
    typia.assert(out_created);
    for (const item of out_created.data) {
      TestValidator.equals("created_at match")(item.created_at)(created);
    }
  }
  if (out_keyword.data.length > 0) {
    const updated = out_keyword.data[0].updated_at;
    const out_updated = await api.functional.discussionboard.configurations.index(connection, {
      body: { updated_at: updated },
    });
    typia.assert(out_updated);
    for (const item of out_updated.data) {
      TestValidator.equals("updated_at match")(item.updated_at)(updated);
    }
  }

  // 5. [id로 단건 검색]
  if (out_keyword.data.length > 0) {
    const id = out_keyword.data[0].id;
    const out_id = await api.functional.discussionboard.configurations.index(connection, { body: { id } });
    typia.assert(out_id);
    for (const item of out_id.data) {
      TestValidator.equals("id match")(item.id)(id);
    }
  }

  // 6. [페이지네이션, 2페이지 요청]
  const out_page1 = await api.functional.discussionboard.configurations.index(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(out_page1);
  const out_page2 = await api.functional.discussionboard.configurations.index(connection, {
    body: { page: 2, limit: 2 },
  });
  typia.assert(out_page2);
  TestValidator.notEquals("page1 vs page2 data")(
    JSON.stringify(out_page1.data),
  )(JSON.stringify(out_page2.data));

  // 7. [orderBy, orderDirection 정렬 테스트]
  const out_order_asc = await api.functional.discussionboard.configurations.index(connection, {
    body: { orderBy: "created_at", orderDirection: "asc", page: 1, limit: 5 },
  });
  const out_order_desc = await api.functional.discussionboard.configurations.index(connection, {
    body: { orderBy: "created_at", orderDirection: "desc", page: 1, limit: 5 },
  });
  typia.assert(out_order_asc);
  typia.assert(out_order_desc);
  if (out_order_asc.data.length > 0 && out_order_desc.data.length > 0) {
    TestValidator.notEquals("ASC/DESC sorting")(
      out_order_asc.data.map((x) => x.id).join(","),
    )(out_order_desc.data.map((x) => x.id).join(","));
  }

  // 8. 각 결과 필드에 대한 타입 및 존재 검증
  for (const result of [out_keyword, out_key, out_value, out_desc, out_page1, out_page2, out_order_asc, out_order_desc]) {
    for (const item of result.data) {
      typia.assert(item);
      TestValidator.predicate("all fields present")(
        typeof item.id === "string" &&
        typeof item.key === "string" &&
        (typeof item.value === "string" || item.value === null || typeof item.value === "undefined") &&
        (typeof item.description === "string" || item.description === null || typeof item.description === "undefined") &&
        typeof item.created_at === "string" &&
        typeof item.updated_at === "string",
      );
    }
  }
}

