      body: {
        key: "",
      } satisfies IDiscussionboardConfiguration.ICreate,
    });
  });

  // 2. Attempt with whitespace-only 'key' (should fail validation)
  await TestValidator.error("whitespace-only 'key' should throw validation error")(async () => {
    await api.functional.discussionboard.configurations.create(connection, {
