/**
 * Test listing of audit logs for the discussion board using various filters and pagination.
 *
 * This function tests the audit log listing API by querying with different filter types, pagination parameters, and invalid values:
 *
 * 1. Query using a specific actor_id (admin/member).
 * 2. Query using a specific action type (e.g., 'post_deleted').
 * 3. Query within a certain date range (created_at_from/to).
 * 4. Query with pagination (page/limit) and verify returned format.
 * 5. Confirm correct handling when no logs match (should return empty result).
 * 6. Edge case: Provide invalid values (e.g., bogus UUID for actor_id, malformed date, negative page/limit) and verify that a validation error occurs with no logs returned.
 *
 * The test creates logically valid random filters, differentiates realistic and invalid queries, ensures contracts for both success and validation errors, and checks returned data matches the filter criteria.
 */
export async function test_api_discussionboard_test_list_audit_logs_with_various_filters(connection: api.IConnection) {
  // 1. List by actor_id (valid UUID)
  const actorId = typia.random<string & tags.Format<"uuid">>();
  const outActorId = await api.functional.discussionboard.auditLogs.index(connection, {
    body: { actor_id: actorId },
  });
  typia.assert(outActorId);
  if (outActorId.data.length > 0) {
    for (const log of outActorId.data) {
      TestValidator.equals("actor_id matches")(log.actor_id)(actorId);
    }
  }

  // 2. List by action type
  const actionType = "post_deleted";
  const outAction = await api.functional.discussionboard.auditLogs.index(connection, {
    body: { action: actionType },
  });
  typia.assert(outAction);
  if (outAction.data.length > 0) {
    for (const log of outAction.data) {
      TestValidator.equals("action matches")(log.action)(actionType);
    }
  }

  // 3. List by date range
  const from = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(); // 7 days ago
  const to = new Date().toISOString();
  const outDate = await api.functional.discussionboard.auditLogs.index(connection, {
    body: { created_at_from: from, created_at_to: to },
  });
  typia.assert(outDate);
  if (outDate.data.length > 0) {
    for (const log of outDate.data) {
      TestValidator.predicate("date in range")(log.created_at >= from && log.created_at <= to);
    }
  }

  // 4. Pagination: get first page with limit=2
  const outPaginated = await api.functional.discussionboard.auditLogs.index(connection, {
    body: { page: 1, limit: 2 },
  });
  typia.assert(outPaginated);
  TestValidator.equals("current page")(outPaginated.pagination.current)(1);
  TestValidator.equals("page limit")(outPaginated.pagination.limit)(2);

  // 5. Confirm handling of no results
  const outEmpty = await api.functional.discussionboard.auditLogs.index(connection, {
    body: { actor_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(outEmpty);
  TestValidator.equals("no results")(outEmpty.data.length)(0);

  // 6. Invalid filter values (expect validation error)
  await TestValidator.error("invalid actor_id format")(() =>
    api.functional.discussionboard.auditLogs.index(connection, {
      body: { actor_id: "not-a-uuid" as any },
    })
  );

  await TestValidator.error("negative limit fails")(() =>
    api.functional.discussionboard.auditLogs.index(connection, {
      body: { limit: -5 as any },
    })
  );

  await TestValidator.error("malformed date fails")(() =>
    api.functional.discussionboard.auditLogs.index(connection, {
      body: { created_at_from: "yesterday" as any },
    })
  );
}

