/**
 * Test updating the payload field of a discussion board audit log as an admin, ensuring only allowed fields are modifiable, and forbidden changes are rejected.
 *
 * Business context:
 * - Audit log update is only for permitted fields (payload for added context/corrections)
 * - Attempts to change core action or attribution fields should be blocked by validation
 * - System must reject updates on non-existent ids
 * - Only compliance-allowed fields may change; audit integrity is paramount
 *
 * Steps:
 * 1. Register an admin user
 * 2. Create an audit log record using that admin as actor
 * 3. Update only the payload field (should succeed, result persisted)
 * 4. Attempt to update forbidden fields (action, actor_id) – expect validation error (skipped: not allowed by type)
 * 5. Attempt to update a non-existent audit log id – expect 404 or error
 * 6. Confirm update succeeded for payload, and forbidden fields remain unchanged
 */
export async function test_api_discussionboard_test_update_audit_log_payload_and_permissions(
  connection: api.IConnection,
) {
  // 1. Register admin member
  const adminInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(20),
    role: "admin",
    is_active: true,
  };
  const admin = await api.functional.discussionboard.members.create(connection, { body: adminInput });
  typia.assert(admin);

  // 2. Create audit log event by admin
  const auditCreateInput: IDiscussionboardAuditLog.ICreate = {
    actor_id: admin.id,
    target_id: null,
    action: "role_assigned",
    payload: JSON.stringify({ context: "initial role grant" }),
  };
  const audit = await api.functional.discussionboard.auditLogs.create(connection, { body: auditCreateInput });
  typia.assert(audit);

  // 3. Update only payload: should be allowed
  const newPayload = JSON.stringify({ context: "Appended context - after review" });
  const updated = await api.functional.discussionboard.auditLogs.update(connection, {
    id: audit.id,
    body: { payload: newPayload },
  });
  typia.assert(updated);
  TestValidator.equals("payload updated")(updated.payload)(newPayload);
  TestValidator.equals("id unchanged")(updated.id)(audit.id);
  TestValidator.equals("actor_id unchanged")(updated.actor_id)(audit.actor_id);
  TestValidator.equals("action unchanged")(updated.action)(audit.action);

  // 4. Attempt update forbidden fields (not implemented – enforced by type, so skipped per requirements)

  // 5. Attempt update to non-existent id
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 update non-existent id")(() =>
    api.functional.discussionboard.auditLogs.update(connection, {
      id: nonExistentId,
      body: { payload: "{\"context\":\"should not update\"}" },
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLog";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";

/**
 * 감사 로그 하드 삭제 기능(e2e):
 *
 * 1. admin 회원을 생성하고, 해당 계정에서 감사 로그를 신규 생성한다.
 * 2. 생성된 감사 로그를 해당 admin 계정으로 하드 삭제(irreversible)한다.
 *    - 이후 복구 불가 & 조회 불가 여부는 조회 API 미제공으로, 실제 조회 검증은 생략.
 * 3. 존재하지 않는 임의의 UUID id에 대해 삭제 요청 시 적절한 에러(404 등)를 발생시키는지 검증한다.
 * 4. admin이 아닌 member 계정의 권한으로 삭제 요청시 거절되어야 하나,
 *    계정 토큰 전환/role switching을 지원하지 않아 실제 권한테스트는 생략한다.
 *
 * @scenario 감사로그(admin) 하드 삭제/예외 케이스 검증
 */
export async function test_api_discussionboard_test_delete_audit_log_by_admin_and_nonexistent_id(
  connection: api.IConnection,
) {
  // 1. admin 회원 생성
  const adminMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(adminMember);

  // 2. 감사 로그 생성 (actor: admin)
  const auditLog: IDiscussionboardAuditLog = await api.functional.discussionboard.auditLogs.create(connection, {
    body: {
      actor_id: adminMember.id,
      action: "settings_changed",
      payload: null,
    } satisfies IDiscussionboardAuditLog.ICreate,
  });
  typia.assert(auditLog);

  // 3. 생성된 감사 로그 하드 삭제 (정상 삭제)
  await api.functional.discussionboard.auditLogs.erase(connection, {
    id: auditLog.id,
  });
  // (별도 조회 API 미제공이라 삭제 후 검증은 생략함)

  // 4. 존재하지 않는 id로 삭제 요청시 에러(404 등) 반환 검증
  const nonExistId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("존재하지 않는 감사로그 id 삭제시 404 에러를 반환해야 한다.")(
    () => api.functional.discussionboard.auditLogs.erase(connection, { id: nonExistId })
  );

  // 5. admin이 아닌 member 계정의 권한 제한 (role switching 미지원으로 실제 테스트는 생략)
  const generalMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(generalMember);
  // (계정/토큰 전환 기능 미지원으로 권한 제한 실제 동작 검증은 불가)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";
import type { IPageIComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIComment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of comments with advanced scenarios:
 *   - Filtering comments by post, author, parent comment, nesting (replies to comments)
 *   - Filtering by creation and update timestamps (date/time windows)
 *   - Filtering soft-deleted (deleted_at) comments
 *   - Edge: no comments under a post, or soft-deleted only
 *   - Pagination and ordering
 *   - Schema integrity for all returned comment fields
 *
 * Steps:
 * 1. Create two posts and two member IDs
 * 2. Create several top-level comments for post A (with different authors)
 * 3. Create replies (child comments) under some comments
 * 4. Attempt to soft-delete one comment and its child (note: as there is no delete endpoint, can only test filter semantics)
 * 5. Issue search/filter requests:
 *    - List all comments for post A
 *    - Filter by author
 *    - Only top-level, only children
 *    - List soft-deleted comments for post A (should be empty in this environment)
 *    - Paginate: two comments per page
 *    - Confirm empty for post B
 *    - For each result, validate fields (deleted_at especially)
 */
export async function test_api_discussionboard_test_list_comments_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two posts and two members
  const memberA = typia.random<string & tags.Format<"uuid">>();
  const memberB = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberA,
      discussionboard_board_id: boardId,
      title: "Post A",
      body: "Body A",
    },
  });
  const postB = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberB,
      discussionboard_board_id: boardId,
      title: "Post B",
      body: "Body B",
    },
  });
  typia.assert(postA);
  typia.assert(postB);

  // 2. Create top-level comments (postA, two authors)
  const commentA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        body: "Top by A",
      },
    },
  );
  const commentA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        body: "Top by B",
      },
    },
  );
  typia.assert(commentA1);
  typia.assert(commentA2);

  // 3. Create replies (children)
  const childA1 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberB,
        parent_id: commentA1.id,
        body: "Reply to Top by A (by B)",
      },
    },
  );
  const childA2 = await api.functional.discussionboard.comments.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA.id,
        discussionboard_member_id: memberA,
        parent_id: commentA2.id,
        body: "Reply to Top by B (by A)",
      },
    },
  );
  typia.assert(childA1);
  typia.assert(childA2);

  // 4. No delete endpoint; can only test semantics of filter with 'deleted'.
  // 5a. List all comments for postA
  const allForPostA = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id } },
  );
  typia.assert(allForPostA);
  allForPostA.data.forEach((comment) => typia.assert(comment));
  allForPostA.data.forEach((c) =>
    TestValidator.equals("post id")(c.discussionboard_post_id)(postA.id),
  );

  // 5b. Filter by author (memberA)
  const byMemberA = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, discussionboard_member_id: memberA } },
  );
  typia.assert(byMemberA);
  byMemberA.data.forEach((comment) => typia.assert(comment));
  byMemberA.data.forEach((c) =>
    TestValidator.equals("author")(c.discussionboard_member_id)(memberA),
  );

  // 5c. Only top-level (parent_id = null)
  const topLevel = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, parent_id: null } },
  );
  typia.assert(topLevel);
  topLevel.data.forEach((comment) => typia.assert(comment));
  topLevel.data.forEach((c) =>
    TestValidator.equals("top-level")(c.parent_id)(null),
  );

  // 5d. Only children for commentA1
  const childrenA1 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, parent_id: commentA1.id } },
  );
  typia.assert(childrenA1);
  childrenA1.data.forEach((comment) => typia.assert(comment));
  childrenA1.data.forEach((c) =>
    TestValidator.equals("parent id")(c.parent_id)(commentA1.id),
  );

  // 5e. Soft-deleted comments (should be empty as within environment we can't delete)
  const deletedOnly = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, deleted: true } },
  );
  typia.assert(deletedOnly);
  deletedOnly.data.forEach((c) =>
    TestValidator.predicate("deleted_at present")(!!c.deleted_at),
  );

  // 5f. Pagination, limit=2, page=1 and 2
  const page1 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, page: 1, limit: 2 } },
  );
  typia.assert(page1);
  page1.data.forEach((comment) => typia.assert(comment));
  const page2 = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postA.id, page: 2, limit: 2 } },
  );
  typia.assert(page2);
  page2.data.forEach((comment) => typia.assert(comment));
  TestValidator.equals("pagination.limit")(page1.pagination.limit)(2);
  TestValidator.equals("pagination.page")(page1.pagination.current)(1);
  TestValidator.equals("pagination.page")(page2.pagination.current)(2);

  // 5g. Post B: should be empty
  const empty = await api.functional.discussionboard.comments.index(
    connection,
    { body: { discussionboard_post_id: postB.id } },
  );
  typia.assert(empty);
  TestValidator.equals("no comments")(empty.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * E2E test for retrieving a discussion board comment by its unique id (GET /discussionboard/comments/{id}).
 *
 * This test validates the following scenarios:
 *
 * 1. Retrieval of an existing, non-deleted comment by id and assertion of all returned schema fields.
 * 2. Retrieval of a soft-deleted comment (deleted_at set) and verification that the deleted_at field is populated.
 * 3. Retrieving a comment by a non-existent (random) id results in a not found error.
 *
 * Prerequisites for the test are:
 *   - Creating a post for comment association.
 *   - Creating two comments for the post with different member ids; one will remain normal and one will be soft-deleted.
 *   - Soft-deleting one of the comments.
 *
 * Steps:
 *   1. Create the required discussion board post entity.
 *   2. Create two comments attached to the post (simulate two different members).
 *   3. Soft-delete the second comment by its id.
 *   4. Retrieve the normal comment by id; verify all fields and that deleted_at is null/undefined.
 *   5. Retrieve the soft-deleted comment by id; verify the deleted_at field is present and is a date-time string.
 *   6. Attempt to retrieve a comment by a random UUID; assert a not found error is thrown.
 */
export async function test_api_discussionboard_test_get_comment_by_id_success_and_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create the discussion post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create two comments for that post
  const comment1 = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment1);
  const comment2 = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(comment2);

  // 3. Soft-delete comment2
  await api.functional.discussionboard.comments.erase(connection, {
    id: comment2.id,
  });

  // 4. Retrieve comment1 by id (should be normal)
  const fetched1 = await api.functional.discussionboard.comments.at(connection, {
    id: comment1.id,
  });
  typia.assert(fetched1);
  TestValidator.equals("fetched1.id matches")(fetched1.id)(comment1.id);
  TestValidator.equals("fetched1.deleted_at is null or absent")(fetched1.deleted_at ?? null)(null);
  TestValidator.equals("fetched1.body matches")(fetched1.body)(comment1.body);
  TestValidator.equals("fetched1.discussionboard_post_id matches")(fetched1.discussionboard_post_id)(comment1.discussionboard_post_id);
  TestValidator.equals("fetched1.discussionboard_member_id matches")(fetched1.discussionboard_member_id)(comment1.discussionboard_member_id);

  // 5. Retrieve comment2 by id (should be soft-deleted)
  const fetched2 = await api.functional.discussionboard.comments.at(connection, {
    id: comment2.id,
  });
  typia.assert(fetched2);
  TestValidator.equals("fetched2.id matches")(fetched2.id)(comment2.id);
  TestValidator.predicate("fetched2.deleted_at exists and is ISO 8601 string")(
    typeof fetched2.deleted_at === "string" && !isNaN(Date.parse(fetched2.deleted_at!))
  );
  // Fields equality
  TestValidator.equals("fetched2.body matches")(fetched2.body)(comment2.body);
  TestValidator.equals("fetched2.discussionboard_post_id matches")(fetched2.discussionboard_post_id)(comment2.discussionboard_post_id);
  TestValidator.equals("fetched2.discussionboard_member_id matches")(fetched2.discussionboard_member_id)(comment2.discussionboard_member_id);

  // 6. Try to retrieve a comment by random id (non-existent)
  await TestValidator.error("should throw for non-existent comment")(() =>
    api.functional.discussionboard.comments.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IComment";

/**
 * Validate creation of comments: root-level and reply with parent_id, plus error edge cases.
 *
 * This test covers end-to-end comment creation logic in a discussion board context:
 *
 * 1. Create a discussion board member (for comment authorship).
 * 2. Create a discussion board post (to attach comments to).
 * 3. Create a root-level comment under the post (with no parent_id).
 * 4. Create a reply comment referencing the previous root-level comment (parent_id).
 * 5. Attempt creation with an invalid/non-existent post_id (expect failure).
 * 6. Attempt creation with an invalid/non-existent member_id (expect failure).
 * 7. Attempt creation with an invalid/non-existent parent_id (expect failure).
 *
 * Expected result: All created comment entities match the schema. All failure scenarios raise errors. Root and reply comments reference correct post/member/parent. Foreign key and required field enforcement is properly handled by the system.
 */
export async function test_api_discussionboard_test_create_comment_with_and_without_parent_id(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(32),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a discussion board post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Create a root-level comment (no parent_id)
  const rootComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(rootComment);
  TestValidator.equals("Comment is top-level")(rootComment.parent_id)(null);
  TestValidator.equals("Comment references correct post")(rootComment.discussionboard_post_id)(post.id);
  TestValidator.equals("Comment authored by member")(rootComment.discussionboard_member_id)(member.id);

  // 4. Create a reply comment referencing the root comment (parent_id)
  const replyComment = await api.functional.discussionboard.comments.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      parent_id: rootComment.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IComment.ICreate,
  });
  typia.assert(replyComment);
  TestValidator.equals("Reply parent matches root comment")(replyComment.parent_id)(rootComment.id);
  TestValidator.equals("Reply references correct post")(replyComment.discussionboard_post_id)(post.id);
  TestValidator.equals("Reply authored by member")(replyComment.discussionboard_member_id)(member.id);

  // 5. Try to create a comment with an invalid post_id (should error)
  await TestValidator.error("Invalid post_id should fail")(() =>
    api.functional.discussionboard.comments.create(connection, {
      body: {
        discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(), // Nonexistent post id
        discussionboard_member_id: member.id,
        body: RandomGenerator.paragraph()(),
      } satisfies IComment.ICreate,
    })
  );

  // 6. Try to create a comment with an invalid member_id (should error)
  await TestValidator.error("Invalid member_id should fail")(() =>
