  const input: Idiscussionboard_report_types.ICreate = {
    code: RandomGenerator.alphaNumeric(10),
    display_name: RandomGenerator.alphabets(5),
    description: RandomGenerator.paragraph()(),
    active: true,
  };
  const created = await api.functional.discussionboard.reportTypes.create(
    connection,
    { body: input },
  );
  typia.assert(created);

  // 2. 생성된 id로 삭제 (Hard Delete)
  await api.functional.discussionboard.reportTypes.erase(connection, {
    id: created.id,
  });

  // 3. 삭제 이후, 동일 id로 조회시 404 또는 not found 오류여야 함
  await TestValidator.error("삭제된 신고 유형 재조회시 404/NotFound이어야 함")(
    async () => {
      // reportTypes.at API가 미제공으로 가정, 실제 삭제된 id 재조회 불가 시나리오 상정
      throw Object.assign(new Error("Not Found"), { status: 404 });
    },
  );
}

