 *
 * Steps:
 * 1. Construct a valid Idiscussionboard_reports.ICreate report data structure.
 * 2. Attempt to submit a report omitting 'target_object_type'.
 * 3. Verify the API properly rejects the request, raising a validation error and not creating the resource.
 * 4. Repeat the process by omitting 'discussionboard_report_type_id' instead.
 * 5. Ensure non-200 HTTP status and a clear error is produced in both omission scenarios.
 * 6. Confirm that optional fields ('report_description') are not required, and absence does not cause validation failure.
 *
 * Expected: Both required-field omission cases should fail with appropriate validation errors. The case omitting the optional field should succeed.
 */
export async function test_api_discussionboard_test_create_moderation_report_with_missing_required_field(
  connection: api.IConnection,
) {
  // Step 1: Build a fully valid payload
  const validReport: Idiscussionboard_reports.ICreate = {
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
    reporting_member_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_id: typia.random<string & tags.Format<"uuid">>(),
    target_object_type: "post",
    report_description: "Test report: user posted illicit spam content."
