 *
 * Step-by-step process:
 * 1. Create a moderation report record to serve as the baseline for update (dependency setup).
 * 2. Construct a mutation payload updating at least two fields (e.g. reason, description, target reference).
 * 3. Perform the update by calling PUT /discussionboard/reports/{id} with the mutation payload.
 * 4. Assert that the response reflects the updated values (and unchanged values remain intact where not provided).
 * 5. Optionally re-fetch or compare the returned object to validate persistence of the update as per contract.
 */
export async function test_api_discussionboard_reports_test_update_moderation_report_success(
  connection: api.IConnection,
) {
  // 1. Create a baseline moderation report
  const createInput: Idiscussionboard_reports.ICreate = {
    discussionboard_report_type_id: typia.random<string & tags.Format<"uuid">>(),
