import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPrivacyPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPrivacyPolicies";
import type { IPageIDiscussionboardPrivacyPolicies } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPrivacyPolicies";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test paginated and filtered listing of privacy policies, including all edge cases.
 *
 * This test validates the privacy policies listing endpoint's ability to handle various query and pagination scenarios:
 *  - Standard retrieval (default pagination)
 *  - Filtering by version, effective_date, and title
 *  - Accurate pagination metadata
 *  - Empty result handling (filters that return no data)
 *  - Handling of invalid filter values (should return error or empty data)
 *  - Confirming that only schema fields appear in responses, and no deleted or archived records are returned (since soft delete is not supported).
 *
 * Steps:
 * 1. Retrieve the first page with default pagination, and validate fields and pagination metadata.
 * 2. Attempt to filter by a random version and validate matching records only (if any), else receives an empty list.
 * 3. Attempt to filter by an effective_date and validate matching or empty results.
 * 4. Attempt to filter by title and validate results.
 * 5. Issue a search that is guaranteed to return nothing (random gibberish in content) and ensure data is empty.
 * 6. Use invalid filter values (bad effective_date, negative page number, zero limit) and validate error or empty result.
 */
export async function test_api_discussionboard_test_list_privacy_policies_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Retrieve with default (no filter, default pagination)
  const defaultList = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: {},
  });
  typia.assert(defaultList);
  // Validate pagination object present
  TestValidator.predicate("default page >= 1")(defaultList.pagination.current >= 1);
  TestValidator.predicate("default limit >= 1")(defaultList.pagination.limit >= 1);
  TestValidator.predicate("records non-negative")(defaultList.pagination.records >= 0);
  // Check for only expected schema fields in each returned item
  const expectedKeys = [
    "id",
    "version",
    "effective_date",
    "title",
    "content",
    "created_at",
    "updated_at"
  ];
  defaultList.data.forEach((policy) => {
    TestValidator.equals("all schema fields present and not extraneous")(
      Object.keys(policy).sort()
    )(expectedKeys);
  });

  // 2. Filter by random version from defaultList or random string
  let testVersion = defaultList.data.length ? defaultList.data[0].version : `v${typia.random<number & tags.Type<"int32"> & tags.Minimum<2020> & tags.Maximum<2099>>()}.XX`;
  const versionList = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { version: testVersion },
  });
  typia.assert(versionList);
  versionList.data.forEach((policy) => {
    TestValidator.equals("version matches")(policy.version)(testVersion);
  });

  // 3. Filter by effective_date from previous list or random
  let testEffDate = defaultList.data.length ? defaultList.data[0].effective_date : new Date().toISOString();
  const effDateList = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { effective_date: testEffDate },
  });
  typia.assert(effDateList);
  effDateList.data.forEach((policy) => {
    TestValidator.equals("effective_date matches")(policy.effective_date)(testEffDate);
  });

  // 4. Filter by title from defaultList or random
  let testTitle = defaultList.data.length ? defaultList.data[0].title : RandomGenerator.alphaNumeric(12);
  const titleList = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { title: testTitle },
  });
  typia.assert(titleList);
  titleList.data.forEach((policy) => {
    TestValidator.equals("title matches")(policy.title)(testTitle);
  });

  // 5. Query that returns empty: gibberish content
  const gibberish = RandomGenerator.alphaNumeric(32);
  const emptyList = await api.functional.discussionboard.privacyPolicies.index(connection, {
    body: { content: gibberish },
  });
  typia.assert(emptyList);
  TestValidator.equals("empty result for gibberish content")(emptyList.data.length)(0);

  // 6. Invalid filters: bad effective_date
  await TestValidator.error("bad effective_date throws")(() =>
    api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { effective_date: "notadate" as any },
    }),
  );

  // Negative page
  await TestValidator.error("negative page number throws")(() =>
    api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { page: -1 as any },
    }),
  );

  // Zero limit
  await TestValidator.error("zero limit throws")(() =>
    api.functional.discussionboard.privacyPolicies.index(connection, {
      body: { limit: 0 as any },
    }),
  );
