 * and checks the update is persisted and reflected in the API response.
 *
 * Steps:
 * 1. Create a board (for assignment)
 * 2. Create a moderator assignment (providing a moderator record)
 * 3. Assign the moderator to the board with is_primary = false
 * 4. Update the assignment to is_primary = true (toggle)
 * 5. Assert that the update succeeded and only the is_primary flag changed
 */
export async function test_api_discussionboard_test_update_board_moderator_assignment_is_primary(
  connection: api.IConnection,
) {
  // 1. Create a board to assign the moderator to
  const boardCreate: IBoard.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: RandomGenerator.alphabets(8),
    code: `board_${RandomGenerator.alphaNumeric(6)}`,
    description: RandomGenerator.paragraph()(),
    is_active: true,
    is_visible: true,
  };
  const board = await api.functional.discussionboard.boards.create(connection, { body: boardCreate });
  typia.assert(board);

  // 2. Create a moderator assignment, which also gives us a moderator id
  const moderatorCreate: IModeratorAssignment.ICreate = {
    member_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_by_admin_id: typia.random<string & tags.Format<"uuid">>(),
    assigned_at: new Date().toISOString(),
    expires_at: null,
  };
  const moderator = await api.functional.discussionboard.moderators.create(connection, { body: moderatorCreate });
  typia.assert(moderator);

