import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IMemberPreference";
import type { IPageIMemberPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMemberPreference";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E 테스트: 멤버 환경설정 리스트 조회 (다양한 필터와 페이지네이션)
 *
 * - 여러 개의 discussionboard 멤버 계정을 만든다.
 * - 각 멤버마다 다양한 조합(이메일/푸시/언어/다크모드)으로 환경설정(Preferences) 레코드를 생성한다.
 * - Preferences 목록 조회 API(discussionboard/memberPreferences.index)에 대해 아래 케이스를 각각 검증한다.
 *   1. 아무 필터 없는 전체 조회 (모든 Preference 반환)
 *   2. receive_email_notifications=true/false 별 필터
 *   3. receive_push_notifications=true/false 별 필터
 *   4. preferred_language 값별 (en/ko/ja 등) 필터
 *   5. dark_mode_enabled=true/false 별 필터
 *   6. 페이지네이션(page/limit) 활용 - 전체 레코드의 2개 단위씩 2페이지
 * - 각 필터와 페이지네이션별로, 결과에 포함된 preference들이 조건을 모두 만족하는지,
 *   불일치 혹은 누락된 레코드가 없는지 검증.
 * - 불필요한 시스템 값이나 soft-delete나 미지원 컬럼 필터는 사용하지 않는다.
 */
export async function test_api_discussionboard_test_list_member_preferences_with_various_filters_and_pagination(connection: api.IConnection) {
  // (1) 여러 개의 멤버 생성
  const members = await Promise.all(ArrayUtil.repeat(5)(async () => {
    const member = await api.functional.discussionboard.members.create(connection, {
      body: {
        username: RandomGenerator.alphaNumeric(8),
        email: typia.random<string & tags.Format<'email'>>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        role: 'member',
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    });
    typia.assert(member);
    return member;
  }));

  // (2) 각 멤버별로 다양한 환경설정 조합 생성
  const prefCombos = [
    { receive_email_notifications: true,  receive_push_notifications: true,  preferred_language: 'en', dark_mode_enabled: true },
    { receive_email_notifications: false, receive_push_notifications: true,  preferred_language: 'ko', dark_mode_enabled: false },
    { receive_email_notifications: true,  receive_push_notifications: false, preferred_language: 'ja', dark_mode_enabled: false },
    { receive_email_notifications: false, receive_push_notifications: false, preferred_language: 'en', dark_mode_enabled: true },
    { receive_email_notifications: null,  receive_push_notifications: null,  preferred_language: null, dark_mode_enabled: null },
  ];
  const preferences = [] as IMemberPreference[];
  for (let i = 0; i < members.length; ++i) {
    const prefInput = { member_id: members[i].id, ...prefCombos[i] } satisfies IMemberPreference.ICreate;
    const pref = await api.functional.discussionboard.memberPreferences.create(connection, { body: prefInput });
    typia.assert(pref);
    preferences.push(pref);
  }

  // (3.1) 전체 목록 조회 테스트
  const allResult = await api.functional.discussionboard.memberPreferences.index(connection, {
    body: {}
  });
  typia.assert(allResult);
  TestValidator.equals('전체 preference')(allResult.data.length)(preferences.length);
  const prefIds = preferences.map(p => p.id).sort();
  const gotIds = allResult.data.map(p => p.id).sort();
  TestValidator.equals('ID 일치')(gotIds)(prefIds);

  // (3.2) receive_email_notifications 필터 테스트
  for (const value of [true, false, null]) {
    const filteredPrefs = preferences.filter(p => p.receive_email_notifications === value);
    if(filteredPrefs.length === 0) continue;
    const result = await api.functional.discussionboard.memberPreferences.index(connection, {
      body: { receive_email_notifications: value },
    });
    typia.assert(result);
    TestValidator.equals(`receive_email_notifications=${value}`)(result.data.length)(filteredPrefs.length);
    filteredPrefs.forEach(p => {
      TestValidator.predicate('receive_email_notifications 필터 일치')(result.data.some(rp => rp.id === p.id));
    });
  }

  // (3.3) receive_push_notifications 필터 테스트
  for (const value of [true, false, null]) {
    const filteredPrefs = preferences.filter(p => p.receive_push_notifications === value);
    if(filteredPrefs.length === 0) continue;
    const result = await api.functional.discussionboard.memberPreferences.index(connection, {
      body: { receive_push_notifications: value },
    });
    typia.assert(result);
    TestValidator.equals(`receive_push_notifications=${value}`)(result.data.length)(filteredPrefs.length);
    filteredPrefs.forEach(p => {
      TestValidator.predicate('receive_push_notifications 필터 일치')(result.data.some(rp => rp.id === p.id));
    });
  }

  // (3.4) preferred_language 필터 테스트
  for (const lang of ['en', 'ko', 'ja', null]) {
    const filteredPrefs = preferences.filter(p => p.preferred_language === lang);
    if(filteredPrefs.length === 0) continue;
    const result = await api.functional.discussionboard.memberPreferences.index(connection, {
      body: { preferred_language: lang },
    });
    typia.assert(result);
    TestValidator.equals(`preferred_language=${lang}`)(result.data.length)(filteredPrefs.length);
    filteredPrefs.forEach(p => {
      TestValidator.predicate(`preferred_language=${lang} 필터 일치`)(result.data.some(rp => rp.id === p.id));
    });
  }

  // (3.5) dark_mode_enabled 필터 테스트
  for (const value of [true, false, null]) {
    const filteredPrefs = preferences.filter(p => p.dark_mode_enabled === value);
    if(filteredPrefs.length === 0) continue;
    const result = await api.functional.discussionboard.memberPreferences.index(connection, {
      body: { dark_mode_enabled: value },
    });
    typia.assert(result);
    TestValidator.equals(`dark_mode_enabled=${value}`)(result.data.length)(filteredPrefs.length);
    filteredPrefs.forEach(p => {
      TestValidator.predicate(`dark_mode_enabled=${value} 필터 일치`)(result.data.some(rp => rp.id === p.id));
    });
  }

  // (3.6) 페이지네이션이 만약 실제로 지원된다면 여기에 limit/page 파라미터 테스트를 추가하되,
  // 현재 DTO 구조상 별도의 입력 필드가 없으므로 패스 또는 주석 처리한다.
}

