  // Step 5: Attempt to update to invalid references (constraint error)
  const invalidThreadId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("Constraint error on invalid post/thread id")(() =>
    api.functional.discussionboard.postReferences.update(connection, {
      id: postRef.id,
      body: {
        target_post_id: typia.random<string & tags.Format<"uuid">>(),
        target_thread_id: invalidThreadId,
        reference_type: "thread",
      } satisfies IPostReference.IUpdate,
    })
  );
}

