  });

  // 5. Try deleting again (should result in error)
  await TestValidator.error("idempotent delete fails for already deleted reference")(
    async () => {
      await api.functional.discussionboard.postReferences.erase(connection, { id: postReference.id });
    },
  );

  // 6. Try deleting random/nonexistent id (should result in error)
  await TestValidator.error("delete fails for nonexistent postReference id")(
    async () => {
      await api.functional.discussionboard.postReferences.erase(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
