import type { Idiscussionboard_report_types } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_report_types";

/**
 * Validate hard deletion of a post report by its unique id.
 *
 * Business context:
 * Moderators may need to remove erroneous or abusive post reports from the moderation queue. Deleting a report should not affect original posts or reporter member data; only the report entity itself will be permanently erased. After successful deletion, no further delete on the same id should succeed, and a 'not found' error or similar should be returned if retried.
 *
 * Test steps:
 * 1. Create a unique member to act as the reporter.
 * 2. Create a report type (active) which will be used for the report.
 * 3. Create a new discussion board post, using referenced entities (member, etc).
 * 4. Create a post report, associating the created post, member, and report type.
 * 5. Hard delete the created post report by its id; verify the operation completes without error.
 * 6. Attempt to hard delete the report again using the same id; confirm that an error or 'not found' response is thrown.
 * 7. Confirm that the original discussion post and member can still be retrieved or inferred as unaffected (cannot verify via read API directly, so just assert the deletion does not throw for unrelated ids).
 */
export async function test_api_discussionboard_test_delete_post_report_success_and_not_found(connection: api.IConnection) {
  // 1. Create a member (reporter).
  const memberInput = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(30),
    role: "member",
    is_active: true,
  } satisfies IDiscussionboardMember.ICreate;
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a report type (active).
  const reportTypeInput = {
    code: RandomGenerator.alphaNumeric(8),
    display_name: "Test Abuse",
    active: true,
    description: "Auto-generated test report type.",
  } satisfies Idiscussionboard_report_types.ICreate;
  const reportType = await api.functional.discussionboard.reportTypes.create(connection, { body: reportTypeInput });
  typia.assert(reportType);

  // 3. Create a post.
  // For post creation, we need thread_id and board_id - use random UUIDs for test isolation.
  const postInput = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
  } satisfies IDiscussionboardPost.ICreate;
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 4. Create a post report for that post.
  const reportInput = {
    discussionboard_post_id: post.id,
    reporter_member_id: member.id,
    report_type_id: reportType.id,
    description: "Inappropriate content detected by automation.",
    created_at: new Date().toISOString(),
  } satisfies Idiscussionboard_post_reports.ICreate;
  const report = await api.functional.discussionboard.postReports.create(connection, { body: reportInput });
  typia.assert(report);

  // 5. Hard delete the created report by its id.
  await api.functional.discussionboard.postReports.erase(connection, { id: report.id });

  // 6. Attempt to delete the report again; should throw (e.g., not found).
  await TestValidator.error("Deleting nonexistent report id must error")(async () => {
    await api.functional.discussionboard.postReports.erase(connection, { id: report.id });
  });

  // 7. (Best effort) Ensure that deleting a fake/unrelated id also errors, but original post/member are unaffected.
  await TestValidator.error("Deleting fake report id must error")(async () => {
    await api.functional.discussionboard.postReports.erase(connection, { id: typia.random<string & tags.Format<"uuid">>() });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBoardSetting";
import type { IPageDiscussionboardBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardBoardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: Validate board settings listing (with filter, sort, and pagination).
 *
 * Simulates an admin accessing the dashboard to:
 * 1. Create several boards and boardSettings (mix of is_locked, require_approval_for_posting, allow_file_uploads, etc.)
 * 2. List with various filters: is_locked, require_approval_for_posting, allow_file_uploads, or combinations
 * 3. Validate each API result contains only settings that match the filter criteria (no leakages)
 * 4. Test pagination logic (page offset + limit)
 * 5. Test response data integrity and proper error response for unsupported fields
 *
 * Full coverage for admin management/analytics with filtering and paging.
 */
export async function test_api_discussionboard_test_list_board_settings_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // -- Step 1: Create several boards with diverse category/section/name/code --
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  // We'll create 5 boards for coverage.
  const boards = await Promise.all(
    ArrayUtil.repeat(5)(() =>
      api.functional.discussionboard.boards.create(connection, {
        body: {
          discussionboard_board_category_id: categoryId,
          discussionboard_section_id: sectionId,
          name: RandomGenerator.paragraph()(),
          code: RandomGenerator.alphaNumeric(8),
          description: RandomGenerator.paragraph()(),
          is_active: true,
          is_visible: true,
        } satisfies IBoard.ICreate,
      })
    )
  );
  for (const board of boards) typia.assert(board);

  // -- Step 2: For each board, create unique settings combo --
  // We'll use a pattern to hit all key filterable fields coverage
  const settingsCombos = [
    { is_locked: true, require_approval_for_posting: true, allow_file_uploads: true },
    { is_locked: false, require_approval_for_posting: true, allow_file_uploads: false },
    { is_locked: true, require_approval_for_posting: false, allow_file_uploads: true },
    { is_locked: false, require_approval_for_posting: false, allow_file_uploads: false },
    { is_locked: true, require_approval_for_posting: true, allow_file_uploads: false },
  ];

  const settings = await Promise.all(
    boards.map((board, i) =>
      api.functional.discussionboard.boardSettings.create(connection, {
        body: {
          discussionboard_board_id: board.id,
          ...settingsCombos[i],
          max_posts_per_hour: 10 + i,
          allow_anonymous_viewing: i % 2 === 0,
        } satisfies IDiscussionboardBoardSetting.ICreate,
      })
    )
  );
  for (const setting of settings) typia.assert(setting);

  // -- Step 3: List with filter: is_locked=true --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { is_locked: true },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("is_locked filter")(s.is_locked)(true);
    }
  }

  // -- Step 4: List with filter: require_approval_for_posting=true --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { require_approval_for_posting: true },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("require_approval_for_posting")(s.require_approval_for_posting)(true);
    }
  }

  // -- Step 5: List with filter: allow_file_uploads=false --
  {
    const result = await api.functional.discussionboard.boardSettings.index(connection, {
      body: { allow_file_uploads: false },
    });
    typia.assert(result);
    for (const s of result.data) {
      TestValidator.equals("allow_file_uploads")(s.allow_file_uploads)(false);
    }
  }

  // -- Step 6: List with combined filters (is_locked=true, allow_file_uploads=true) --
  {
