/**
 * 섹션 리스트 조회의 검색/페이징 로직을 실제 필터마다 검증
 *
 * 다양한 필터(name, code, active)와 페이징(page/limit)을 적용하여 section 리스트 조회가 올바르게 동작하는지 확인한다. 
 * - 사전: 최소 2개 section을 서로 다른 속성(이름, 코드, 활성상태)으로 생성한다.
 * - 이후 각각의 필터로 조회 시 해당 섹션만 반환되는지,
 *   모든 응답 데이터가 올바른 스키마(candidate) 필드를 포함하는지,
 *   pagination 정보가 정상인지,
 *   없는 name/code 검색 시 빈 결과가 나오는지 검증한다.
 *
 * 검증 대상:
 * 1. name(이름) 필터
 * 2. code(고유코드) 필터
 * 3. active(활성/비활성)
 * 4. page, limit (페이징)
 * 5. 존재하지 않는 name (빈 리스트)
 */
export async function test_api_discussionboard_test_list_sections_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트용 channel id 발급
  const channelId = typia.random<string & tags.Format<"uuid">>();

  // 2. section 2개를 서로 다른 name/code/active로 생성
  const section1Input = {
    discussionboard_channel_id: channelId,
    code: RandomGenerator.alphaNumeric(8),
    name: "테스트섹션A",
    description: "설명A",
    position: 1,
    active: true,
  } satisfies IDiscussionboardSection.ICreate;
  const section2Input = {
    discussionboard_channel_id: channelId,
    code: RandomGenerator.alphaNumeric(8),
    name: "테스트섹션B",
    description: "설명B",
    position: 2,
    active: false,
  } satisfies IDiscussionboardSection.ICreate;

  const section1 = await api.functional.discussionboard.sections.create(connection, { body: section1Input });
  typia.assert(section1);
  const section2 = await api.functional.discussionboard.sections.create(connection, { body: section2Input });
  typia.assert(section2);

  // 3-1. name 단독 필터(섹션1)
  let res = await api.functional.discussionboard.sections.index(connection, { body: { name: section1.name, discussionboard_channel_id: channelId } });
  typia.assert(res);
  TestValidator.predicate("name 필터 결과 1개")(res.data.length === 1);
  TestValidator.equals("name by section1")(res.data[0].id)(section1.id);
  for(const sec of res.data) typia.assert(sec);

  // 3-2. code 단독 필터(섹션2)
  res = await api.functional.discussionboard.sections.index(connection, { body: { code: section2.code, discussionboard_channel_id: channelId } });
  typia.assert(res);
  TestValidator.predicate("code 필터 결과 1개")(res.data.length === 1);
  TestValidator.equals("code by section2")(res.data[0].id)(section2.id);

  // 3-3. active: true => section1만
  res = await api.functional.discussionboard.sections.index(connection, { body: { active: true, discussionboard_channel_id: channelId } });
  typia.assert(res);
  TestValidator.predicate("active=true 결과 1개")(res.data.length === 1);
  TestValidator.equals("active true section")(res.data[0].id)(section1.id);

  // 3-4. active: false => section2만
  res = await api.functional.discussionboard.sections.index(connection, { body: { active: false, discussionboard_channel_id: channelId } });
  typia.assert(res);
  TestValidator.predicate("active=false 결과 1개")(res.data.length === 1);
  TestValidator.equals("active false section")(res.data[0].id)(section2.id);

  // 3-5. 페이징(page=1, limit=1): 첫번째 section 반환
  res = await api.functional.discussionboard.sections.index(connection, { body: { discussionboard_channel_id: channelId, page: 1, limit: 1 } });
  typia.assert(res);
  TestValidator.predicate("limit=1 반환 1개")(res.data.length === 1);
  TestValidator.equals("pagination 첫번째 section")(res.data[0].id)(section1.id);
  TestValidator.equals("pagination.limit")(res.pagination.limit)(1);

  // 4. 존재하지 않는 name 검색: 빈 리스트
  res = await api.functional.discussionboard.sections.index(connection, { body: { name: "존재하지않는섹션", discussionboard_channel_id: channelId } });
  typia.assert(res);
  TestValidator.predicate("non-existing name 반환 0개")(res.data.length === 0);
}

