 *
 * This test ensures that when a section is created, the API allows fetching its full detail using its unique ID. It covers both resource creation and retrieval, and cross-checks all schema-defined fields to make sure nothing is omitted or mismatched.
 *
 * Steps:
 * 1. Create a discussionboard section via the create endpoint.
 * 2. Retrieve the section using the section's ID by calling the getById endpoint.
 * 3. Assert that all returned fields (id, discussionboard_channel_id, code, name, description, position, active, created_at, updated_at) match those from the initial creation response.
 */
export async function test_api_discussionboard_test_get_section_by_id_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a discussion board section with random valid data
  const sectionInput: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.alphabets(10),
