/**
 * 테스트: 인증되지 않았거나 관리자가 아닌 사용자가 게시판 섹션을 수정할 때 거부되는지 확인합니다.
 *
 * 이 테스트는 게시판 섹션 업데이트 API가 적절한 권한 검사를 수행하는지 검증합니다.
 * 1) 우선 정상 권한으로 섹션을 생성합니다. (의존성 단계)
 * 2) 인증되지 않은 상태(Authorization 헤더가 없는 연결 정보)로 섹션 수정을 시도합니다.
 * 3) API가 권한 에러(Http 401/403 등)로 요청을 거부하는지 검증합니다.
 *
 * [테스트 흐름]
 * 1. 유효한 섹션 데이터를 생성하여 discussionboard.sections.create로 섹션 레코드를 만듭니다.
 * 2. Authorization 헤더가 없는 connection으로 update API 호출 시도
 * 3. TestValidator.error를 통해 반드시 권한 관련 에러가 발생하는지 확인
 */
export async function test_api_discussionboard_test_update_section_without_authorization(
  connection: api.IConnection,
) {
  // 1. 테스트용 섹션 생성 (setup 단계)
  const sectionInput: IDiscussionboardSection.ICreate = {
    discussionboard_channel_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.alphabets(8),
    position: typia.random<number & tags.Type<"int32">>(),
    active: true,
    description: RandomGenerator.alphabets(15),
  };
  const section = await api.functional.discussionboard.sections.create(connection, { body: sectionInput });
  typia.assert(section);

  // 2. Authorization 헤더 제거(권한 없는 상태)로 section update 시도
  const updateInput: IDiscussionboardSection.IUpdate = {
    discussionboard_channel_id: section.discussionboard_channel_id,
    code: section.code + "_edit",
    name: section.name + "_edited",
    position: section.position,
    active: !section.active,
    description: section.description ? section.description + "_updated" : "temp updated desc",
  };
  // 인증 없이 호출: Authorization 헤더 명시적으로 삭제
  const unauthConn = { ...connection, headers: { ...connection.headers } };
  if (unauthConn.headers) delete unauthConn.headers["Authorization"];
  await TestValidator.error("권한 없는 update 요청은 반드시 거절되어야 함")(async () => {
    await api.functional.discussionboard.sections.update(unauthConn, {
      id: section.id,
      body: updateInput,
    });
  });
}

