 *
 * - 스키마 필드 외 값 노출 여부 검증: 반환키 Object.keys 정렬로 strict 체크
 * - 관리자 권한 인증 API가 없으므로, acting_moderator_id는 직접 생성한 admin member id를 사용
 *
 *
 * @author Wrtn AutoBE
 */
export async function test_api_discussionboard_test_retrieve_warning_by_id_with_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버 생성(경고 받을 멤버)
  const memberReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(12),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberReq });
