  // 2. 테스트용 관리자 생성(acting_moderator_id 부여 목적)
  const moderatorReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(14),
    role: "admin",
    is_active: true,
