  typia.assert(moderator);

  // 3. 경고(warning) 발급 (report_id=null: 인시던트 미연결)
  const now = new Date().toISOString();
  const warningReq: IDiscussionboardWarning.ICreate = {
    warned_member_id: member.id,
    acting_moderator_id: moderator.id,
    report_id: null,
    reason: "테스트 경고 사유: 정책 위반",
    warned_at: now,
  };
  const warning = await api.functional.discussionboard.warnings.create(connection, { body: warningReq });
  typia.assert(warning);

  // 4. 정상 id 상세조회: 모든 필드 일치 및 스키마 외 값 없음 보장
  const detail = await api.functional.discussionboard.warnings.at(connection, { id: warning.id });
