import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Validate backend enforcement of required fields on warning creation.
 *
 * This test ensures that the API for creating new moderator warnings rejects requests missing any required fields—warned_member_id, acting_moderator_id, reason, or warned_at. For each required field, attempt to create a warning with that field missing (do not supply the property at all). Confirm that the API triggers a validation error, preventing record creation. These checks ensure the backend models, DTOs and OpenAPI schema correctly mark each property as non-optional and that system integrity is preserved by refusing under-complete records.
 *
 * Steps:
 * 1. Generate a valid IDiscussionboardWarning.ICreate payload.
 * 2. For each required field, construct a payload omitting that field.
 * 3. Attempt warning creation with the incomplete payload.
 * 4. Confirm the system throws a validation error for each case.
 * 5. Ensure no records are created for invalid requests.
 */
export async function test_api_discussionboard_test_create_warning_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Generate a valid payload
  const validPayload = {
    warned_member_id: typia.random<string & tags.Format<"uuid">>(),
    acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    reason: "Test reason for warning",
    warned_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  // 2. Test error when missing warned_member_id
  {
    const { warned_member_id, ...body } = validPayload;
    TestValidator.error("missing warned_member_id triggers validation error")(
      async () => {
        // @ts-expect-error: intentionally omitting required field for negative test
        await api.functional.discussionboard.warnings.create(connection, { body });
      },
    );
  }
  // 3. Test error when missing acting_moderator_id
  {
    const { acting_moderator_id, ...body } = validPayload;
    TestValidator.error("missing acting_moderator_id triggers validation error")(
      async () => {
        // @ts-expect-error: intentionally omitting required field for negative test
        await api.functional.discussionboard.warnings.create(connection, { body });
      },
    );
  }
  // 4. Test error when missing reason
  {
    const { reason, ...body } = validPayload;
    TestValidator.error("missing reason triggers validation error")(
      async () => {
        // @ts-expect-error: intentionally omitting required field for negative test
        await api.functional.discussionboard.warnings.create(connection, { body });
      },
    );
  }
  // 5. Test error when missing warned_at
  {
    const { warned_at, ...body } = validPayload;
    TestValidator.error("missing warned_at triggers validation error")(
      async () => {
        // @ts-expect-error: intentionally omitting required field for negative test
        await api.functional.discussionboard.warnings.create(connection, { body });
      },
    );
  }
}

