) {
  // 1. Attempt to create warning with a non-existent warned_member_id
  await TestValidator.error("non-existent warned_member_id should result in error")(async () => {
    await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Test with non-existent warned_member_id",
        warned_at: new Date().toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    });
  });

  // 2. Attempt to create warning with a non-existent acting_moderator_id
  await TestValidator.error("non-existent acting_moderator_id should result in error")(async () => {
    await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Test with non-existent acting_moderator_id",
        warned_at: new Date().toISOString(),
      } satisfies IDiscussionboardWarning.ICreate,
    });
  });

  // 3. Attempt to create warning with invalid warned_at format
  await TestValidator.error("invalid warned_at format should result in error")(async () => {
    await api.functional.discussionboard.warnings.create(connection, {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Test with invalid warned_at format",
        warned_at: "invalid-date-format",
      } satisfies IDiscussionboardWarning.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Test updating a warning record with valid fields and verify business rules.
 *
 * 본 테스트는 discussionboard_warnings API의 update 동작을 검증합니다. 
 *
 * 1. member(일반 사용자) 및 moderator(경고 발급자) 계정 생성.
 * 2. moderator 권한으로 warning(경고) 레코드 발급.
 * 3. warning의 allowed 필드(reason, warned_at, acting_moderator_id, report_id)를 새로운 값으로 업데이트 시도 및 변경 결과 확인.
 * 4. 응답 및 persisted 결과가 모두 요청값과 일치하는지 확인.
 * 5. 불변(id 등) 또는 존재하지 않는 필드로 업데이트 시도시 에러가 발생하는지 검증.
 * 6. (API가 지원한다면) 권한 없는 member 계정이 update 시도시 에러가 발생함을 확인.
 */
export async function test_api_discussionboard_test_update_warning_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. 일반 사용자(member) 계정 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. moderator 계정 생성
  const moderator = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "moderator",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(moderator);

  // 3. moderator가 member에게 warning 발급
  const warning = await api.functional.discussionboard.warnings.create(connection, {
    body: {
      warned_member_id: member.id,
      acting_moderator_id: moderator.id,
      reason: "Spamming threads excessively.",
      warned_at: new Date().toISOString(),
      report_id: null,
    } satisfies IDiscussionboardWarning.ICreate,
  });
  typia.assert(warning);

  // 4. allowed 필드(reason, warned_at, acting_moderator_id, report_id) 수정
  const update_patch = {
    warned_member_id: member.id, // 기본은 동일(테스트 목적상 유지)
    acting_moderator_id: moderator.id, // 동일(혹은 후속 테스트시 admin 계정 등 다른 값으로)
    reason: "Updated reason: Inappropriate language.",
    warned_at: new Date(Date.now() + 60 * 60 * 1000).toISOString(), // +1h
    report_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionboardWarning.IUpdate;

  const updated = await api.functional.discussionboard.warnings.update(connection, {
    id: warning.id,
    body: update_patch,
  });
  typia.assert(updated);

  // 5. 요청 patch값과 응답이 동일한지 확인 (id는 불변)
  TestValidator.equals("updated warning, patch reflected")(updated)({
    ...warning,
    ...update_patch,
    id: warning.id,
  });

  // 6. 불변/존재안하는 필드 입력시 에러 발생 검증(id, not_a_field)
  TestValidator.error("immutable or nonexistent field update must fail")(
    async () => {
      await api.functional.discussionboard.warnings.update(connection, {
        id: warning.id,
        body: {
          ...update_patch,
          id: typia.random<string & tags.Format<"uuid">>(), // 불변 PK 수정 불가
          not_a_field: "should fail", // 스키마에 없는 필드
        } as any, // 일부러 타입을 맞추기 위해 명시적 any (런타임 검증 목적)
      });
    },
  );

  // 7. 권한 없는 member가 update 시도시 에러(권한 체크가 실제 구현되어 있다면)
  // (실제 시스템이 인증/권한을 강제 적용 중인 경우 아래 코드 활성화 가능)
  // TestValidator.error("member forbidden to update warning")(
  //   async () => {
  //     await api.functional.discussionboard.warnings.update(connection, {
  //       id: warning.id,
  //       body: update_patch,
  //     });
  //   },
  // );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardWarning } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardWarning";

/**
 * Validate error handling when updating a warning record with an invalid or non-existent ID.
 *
 * This e2e test covers two main negative scenarios for warning update:
 *
 * 1. Attempting to update a warning using a random, non-existent warning ID (should result in not-found error).
 * 2. Attempting to update a real warning with valid TypeScript structure, but a business-invalid scenario (e.g., reusing the same data, redundant update, or edge business cases).
 *
 * Due to technical limitations of type system, scenarios attempting to send missing required fields or deliberately mal-typed inputs (e.g., invalid UUIDs, missing required properties) are omitted, as they are caught by TypeScript at compile time per the SDK and DTO typing contracts.
 *
 * Workflow:
 * 1. Create a valid warning record (prerequisite).
 * 2. Attempt to update a warning with a random, definitely non-existent warning ID; expect a not-found error.
 * 3. Update the warning with a valid change and assert the result is correctly reflected.
 */
export async function test_api_discussionboard_test_update_warning_with_invalid_id_or_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid warning (prerequisite for update and to check later correctness)
  const validWarning = await api.functional.discussionboard.warnings.create(
    connection,
    {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Initial warning reason for negative update test.",
        warned_at: new Date().toISOString(),
        report_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(validWarning);

  // 2. Try updating with a non-existent id (must get not found error)
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();
  TestValidator.error("should return not found for non-existent warning id")(
    async () => {
      await api.functional.discussionboard.warnings.update(connection, {
        id: nonExistentId,
        body: {
          warned_member_id: typia.random<string & tags.Format<"uuid">>(),
          acting_moderator_id: typia.random<string & tags.Format<"uuid">>(),
          reason: "Some new reason for not-found test",
          warned_at: new Date().toISOString(),
        },
      });
    },
  );

  // 3. Update with valid, non-edge-case payload; should succeed
  const updatedWarning = await api.functional.discussionboard.warnings.update(
    connection,
    {
      id: validWarning.id,
      body: {
        warned_member_id: validWarning.warned_member_id,
        acting_moderator_id: validWarning.acting_moderator_id,
        reason: "Updated after negative scenario test.",
        warned_at: new Date().toISOString(),
        report_id: validWarning.report_id ?? null,
      },
    },
  );
  typia.assert(updatedWarning);
  TestValidator.equals("reason is updated")(
    updatedWarning.reason
  )("Updated after negative scenario test.");
}

