  out = await api.functional.discussionboard.settings.index(connection, {
    body: {
      value: "__does_not_exist__",
    },
  });
  typia.assert(out);
  TestValidator.equals("No results on nonsense filter")(out.data.length)(0);
  TestValidator.equals("No results pagination records")(out.pagination.records)(0);
}

