/**
 * Test updating a discussionboard setting with valid data (PUT /discussionboard/settings/{id})
 *
 * This test validates the update functionality for a settings record in discussionboard_settings. It verifies field-level updates (value and description), nullability transitions, and confirms that primary identifiers and unique constraint fields remain stable. The workflow ensures both full and partial updates work as designed, including toggling fields between string and null types.
 *
 * **Test Workflow:**
 * 1. Create a new discussionboard setting via POST /discussionboard/settings to obtain a valid record.
 * 2. Update the 'value' and 'description' fields using PUT /discussionboard/settings/{id}, checking the API applies all updates and preserves other fields.
 * 3. Update only the 'description' field (set it to null), ensuring 'value' remains stable and partial updates work as expected.
 * 4. Change 'value' to null and back to a string, verifying nullability transitions.
 * 5. After each update, confirm that 'id', 'key', 'scope_type', and other non-updated fields remain unchanged, and updates are correctly reflected in the response.
 *
 * This test does not deliberately violate constraints (such as unique keys) as such tests are out of scope for this scenario.
 */
export async function test_api_discussionboard_test_update_setting_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new discussionboard setting as baseline (dependency)
  const createInput: IDiscussionboardSetting.ICreate = {
    scope_id: null, // global-level setting
    scope_type: "feature_flag",
    key: RandomGenerator.alphabets(10),
    value: "true",
    description: "initial feature flag for test run",
  };
  const original = await api.functional.discussionboard.settings.create(connection, { body: createInput });
  typia.assert(original);

  // 2. Update 'value' and 'description'
  const updateInput1: IDiscussionboardSetting.IUpdate = {
    value: "false",
    description: "changed for verification"
  };
  const updated1 = await api.functional.discussionboard.settings.update(connection, {
    id: original.id,
    body: updateInput1,
  });
  typia.assert(updated1);
  TestValidator.equals("id remains")(updated1.id)(original.id);
  TestValidator.equals("key remains unchanged")(updated1.key)(original.key);
  TestValidator.equals("scope_type remains unchanged")(updated1.scope_type)(original.scope_type);
  TestValidator.equals("value updated")(updated1.value)(updateInput1.value);
  TestValidator.equals("description updated")(updated1.description)(updateInput1.description);

  // 3. Update only 'description' to null, ensure value is unchanged
  const updateInput2: IDiscussionboardSetting.IUpdate = {
    description: null
  };
  const updated2 = await api.functional.discussionboard.settings.update(connection, {
    id: original.id,
    body: updateInput2,
  });
  typia.assert(updated2);
  TestValidator.equals("id remains")(updated2.id)(original.id);
  TestValidator.equals("key remains unchanged")(updated2.key)(original.key);
  TestValidator.equals("scope_type remains unchanged")(updated2.scope_type)(original.scope_type);
  TestValidator.equals("value still 'false'")(updated2.value)(updateInput1.value);
  TestValidator.equals("description set to null")(updated2.description)(null);

  // 4. Set value to null, then restore string
  await api.functional.discussionboard.settings.update(connection, {
    id: original.id,
    body: { value: null },
  });
  const updated3 = await api.functional.discussionboard.settings.update(connection, {
    id: original.id,
    body: { value: "new-string-value" },
  });
  typia.assert(updated3);
  TestValidator.equals("id remains")(updated3.id)(original.id);
  TestValidator.equals("value updated to string")(updated3.value)("new-string-value");
}

