  typia.assert(comment);

  // 3. Record a valid vote ("up")
  const voteInput = {
    discussionboard_comment_id: comment.id,
    discussionboard_member_id: member.id,
    vote_type: "up",
  } satisfies IDiscussionboardCommentVote.ICreate;
  const vote = await api.functional.discussionboard.commentVotes.create(connection, { body: voteInput });
