  typia.assert(byAdmin);
  TestValidator.predicate("assigned_by_admin_id 일치")(byAdmin.data.every(a => a.assigned_by_admin_id === admin.id));

  // 6. 활성 assignment만(revoked_at=null)
  const nowIso = new Date().toISOString();
  const activeAssignments = await api.functional.discussionboard.moderators.index(connection, {
    body: { revoked_at: null },
