import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IModeratorAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IModeratorAssignment";

/**
 * Validate update logic of moderator assignment records via /discussionboard/moderators/{id} (PUT).
 *
 * Business context:
 * - A moderator assignment links a member to moderator privileges, assigned by an admin.
 * - Updating allows for changing the responsible admin, extending/shortening the assignment, or revoking privileges.
 *
 * Steps:
 * 1. Create two discussionboard members: one normal member, one admin. Both must be active, with unique usernames/emails.
 * 2. Create a moderator assignment record--grants moderator to the member, assigned by admin, with current timestamp and no expiry.
 * 3. Update the assignment by id, setting:
 *    - a) assigned_by_admin_id (simulate reassignment)
 *    - b) expires_at (set a future date for timed expiration)
 *    - c) revoked_at (set to now, making assignment revoked)
 * 4. Confirm all above fields are reflected in assignment after update.
 * 5. Error test: try update with a random (non-existent) id, expect 404 error.
 * 6. Error test: try update with invalid timestamp (e.g., malformed or impossible value), expect validation error.
 */
export async function test_api_discussionboard_test_update_moderator_assignment_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Create member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 1. Create admin
  const admin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(admin);

  // 2. Create moderator assignment
  const assignment = await api.functional.discussionboard.moderators.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: admin.id,
      assigned_at: new Date().toISOString(),
      expires_at: null,
    } satisfies IModeratorAssignment.ICreate,
  });
  typia.assert(assignment);

  // 3. Prepare update: new admin, new expiry, and revoke now
  // Create new admin for reassignment
  const newAdmin = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(20),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(newAdmin);

  const newExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
  const revokedAt = new Date().toISOString();

  // 4. Update assignment fields (simulate multiple updates at once)
  const updated = await api.functional.discussionboard.moderators.update(connection, {
    id: assignment.id,
    body: {
      assigned_by_admin_id: newAdmin.id,
      expires_at: newExpiresAt,
      revoked_at: revokedAt,
    } satisfies IModeratorAssignment.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("assigned_by_admin_id change")(updated.assigned_by_admin_id)(newAdmin.id);
  TestValidator.equals("expires_at change")(updated.expires_at)(newExpiresAt);
  TestValidator.equals("revoked_at set")(updated.revoked_at)(revokedAt);

  // 5. Error: Non-existent id
  await TestValidator.error("404 on non-existent id update")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        assigned_by_admin_id: newAdmin.id,
      } satisfies IModeratorAssignment.IUpdate,
    });
  });

  // 6. Error: Invalid timestamp value (malformed string for date field)
  await TestValidator.error("invalid timestamp")(async () => {
    await api.functional.discussionboard.moderators.update(connection, {
      id: assignment.id,
      body: {
        expires_at: "not-a-date-time",
      } satisfies IModeratorAssignment.IUpdate,
    });
  });
}

