 * and never leaks sensitive credentials like hashed_password.
 *
 * Step-by-step process:
 * 1. Create a member account to obtain a valid id
 * 2. Retrieve member details by id
 * 3. Assert all key fields match and response never includes sensitive info
 * 4. Validate logic for status fields like is_active/deleted_at
 */
export async function test_api_discussionboard_test_get_member_details_when_member_exists(
  connection: api.IConnection,
) {
  // 1. Create a new member to test with
  const memberCreateInput = {
    username: RandomGenerator.alphaNumeric(12),
