import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate discussion thread listing with filtering and pagination.
 *
 * Ensures that filtering by board and author works correctly and pagination meta is accurate.
 * The test executes a complete scenario by creating a board, a member, several threads, and
 * then listing them using the API, validating both returned data and pagination.
 *
 * Steps:
 * 1. Create a board.
 * 2. Create a member.
 * 3. Create several threads under that board by that member.
 * 4. Query threads by board_id and author_member_id using pagination.
 * 5. Check all returned threads match the filters.
 * 6. Assert pagination metadata is correct.
 */
export async function test_api_discussionboard_test_list_threads_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board: IBoard = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(2),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(1),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 2. Create a member (author)
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 3. Create multiple threads by the member on the board
  const threadCount = 7;
  const createdThreads: IDiscussionboardThreads[] = [];
  for (let i = 0; i < threadCount; ++i) {
    const thread: IDiscussionboardThreads = await api.functional.discussionboard.threads.create(connection, {
      body: {
        board_id: board.id,
        author_member_id: member.id,
        title: `${RandomGenerator.paragraph()(1)} #${i + 1}`,
        body: i % 2 === 0 ? RandomGenerator.content()()() : undefined,
      } satisfies IDiscussionboardThreads.ICreate,
    });
    typia.assert(thread);
    createdThreads.push(thread);
  }

  // 4. List threads with both filters and pagination (page 1, limit 3)
  const page = 1;
  const limit = 3;
  const pageResult = await api.functional.discussionboard.threads.index(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      page,
      limit,
    } satisfies IDiscussionboardThreads.IRequest,
  });
  typia.assert(pageResult);

  // 5. Check each returned thread satisfies filter criteria
  for (const thread of pageResult.data) {
    TestValidator.equals("board_id correct")(thread.board_id)(board.id);
    TestValidator.equals("author_member_id correct")(thread.author_member_id)(member.id);
  }

  // 6. Assert pagination is correct
  TestValidator.equals("pagination.current")(pageResult.pagination.current)(page);
  TestValidator.equals("pagination.limit")(pageResult.pagination.limit)(limit);
  TestValidator.predicate("returned thread count <= limit")(pageResult.data.length <= limit);
  TestValidator.predicate("pagination.records >= returned threads")(
    pageResult.pagination.records >= pageResult.data.length,
  );

  // Optionally, fetch all threads and check all are present.
  const allResults = await api.functional.discussionboard.threads.index(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      limit: threadCount,
    } satisfies IDiscussionboardThreads.IRequest,
  });
  typia.assert(allResults);
  TestValidator.equals("all created threads retrieved")(
    allResults.data.length,
  )(threadCount);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { ISoftDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/ISoftDeleteConfirmation";

/**
 * Validates that the thread list API includes soft-deleted threads when requested, enabling reliable moderation, audit, and recovery flows.
 *
 * Business context:
 * Discussion/community platforms often employ "soft delete" (setting deleted_at to non-null) for threads and posts to allow admins to restore content or maintain audit trails for future reference. Systems must provide a mechanism for discovering soft-deleted records when required (e.g., moderation, compliance, analytics).
 *
 * This test verifies that:
 * - When a thread is soft-deleted (deleted_at set), it is excluded from normal queries, but
 * - When the threads list endpoint is queried with deleted_at_set: true, the soft-deleted thread appears in the results and has deleted_at set.
 *
 * Process:
 * 1. Create a discussion board member to serve as author.
 * 2. Create a board where threads can be posted.
 * 3. Create a new thread owned by that member within the board.
 * 4. Soft-delete the thread using the erase (DELETE) endpoint.
 * 5. List threads in the board using the filter deleted_at_set: true.
 * 6. Assert the soft-deleted thread appears in results and that its deleted_at is populated, ensuring compliance with soft-delete business logic and enabling downstream recovery and audit scenarios.
 */
export async function test_api_discussionboard_test_list_threads_include_soft_deleted(
  connection: api.IConnection,
) {
  // 1. Create a discussion board member (thread author)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(24),
      role: "member",
      is_active: true
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a board where the thread will be posted
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphaNumeric(12),
      code: RandomGenerator.alphaNumeric(10),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 3. Create a new thread
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Soft-delete the thread using the DELETE endpoint
  const confirmation = await api.functional.discussionboard.threads.erase(connection, {
    id: thread.id,
  });
  typia.assert(confirmation);
  TestValidator.equals("soft_deleted must be true")(confirmation.soft_deleted)(true);
  TestValidator.equals("confirmation id matches thread")(confirmation.id)(thread.id);

  // 5. Query threads with filter deleted_at_set: true and board_id
  const threadList = await api.functional.discussionboard.threads.index(connection, {
    body: {
      board_id: board.id,
      deleted_at_set: true
    } satisfies IDiscussionboardThreads.IRequest,
  });
  typia.assert(threadList);

  // 6. Assert the soft-deleted thread appears in the result with deleted_at populated
  const softDeleted = threadList.data.find(t => t.id === thread.id);
  TestValidator.predicate("Soft-deleted thread is present in listing")(!!softDeleted);
  if (!softDeleted) {
    throw new Error(
      `Soft-deleted thread not found (thread id: ${thread.id}, board id: ${board.id}) in thread list response`
    );
  }
  TestValidator.predicate("Thread deleted_at must not be null")(softDeleted.deleted_at != null);
}

