import type { ISoftDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/ISoftDeleteConfirmation";

/**
 * 검증: 소프트 딜리트(soft-delete)된 토론 스레드를 id로 조회할 수 있는지 확인합니다.
 *
 * - 시나리오 흐름 및 비즈니스 목적:
 *   1. 게시판(board)을 생성합니다.
 *   2. 스레드 생성 회원(member)을 만듭니다.
 *   3. 게시판과 회원 id로 thread(스레드)를 생성합니다.
 *   4. 해당 스레드를 soft-delete(논리삭제) 요청으로 삭제합니다.
 *   5. 삭제(soft-deleted)된 스레드를 id로 재조회합니다.
 *   6. 반환된 thread의 deleted_at 값이 null이 아니고, 생성 당시의 title, body, board_id, author_member_id 값이 보존되어 있는지 확인합니다.
 *
 * - 실패 케이스:
 *   1. 없는 id로 조회 시 not found가 발생하는지 별도 테스트에서 다룹니다. 본 케이스에서는 soft-delete 후 정상 조회 확인에 집중합니다.
 *
 * - 커버리지 목표:
 *   - 삭제된(recycle bin 내림) thread에 대한 직접 조회 API 정상동작.
 *   - deleted_at 등 주요 필드 불변성 유지.
 */
export async function test_api_discussionboard_test_get_soft_deleted_thread_by_id(
  connection: api.IConnection,
) {
  // 1. 게시판(board) 생성
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 2. 스레드 생성 회원(member) 생성
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 3. 게시판-회원 기반 스레드 생성
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. 스레드 soft-delete (논리삭제)
  const eraseConf = await api.functional.discussionboard.threads.erase(connection, {
    id: thread.id,
  });
  typia.assert(eraseConf);
  TestValidator.predicate("Confirmed soft-deletion")(eraseConf.soft_deleted === true);
  TestValidator.equals("Deleted thread id matches")(eraseConf.id)(thread.id);

  // 5. soft-deleted thread 재조회
  const readThread = await api.functional.discussionboard.threads.at(connection, {
    id: thread.id,
  });
  typia.assert(readThread);

  // 6. 상태 및 필드 검증
  TestValidator.equals("deleted_at must be set (not null)")(typeof readThread.deleted_at === "string" && readThread.deleted_at !== null)(true);
  TestValidator.equals("title preserved")(readThread.title)(thread.title);
  TestValidator.equals("body preserved")(readThread.body)(thread.body);
  TestValidator.equals("author_member_id preserved")(readThread.author_member_id)(member.id);
  TestValidator.equals("board_id preserved")(readThread.board_id)(board.id);
}

