  );

  // 3. Attempt to create a thread with a bad board_id (likely) and new random author_member_id
  await TestValidator.error("should fail with bad board_id only")(
    async () => {
      await api.functional.discussionboard.threads.create(connection, {
        body: {
          board_id: badBoardId,
          author_member_id: typia.random<string & tags.Format<"uuid">>(),
          title: "Should Fail: Nonexistent Board",
        } satisfies IDiscussionboardThreads.ICreate,
      });
    },
  );

