import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * Validate thread update API input validation for invalid fields.
 *
 * This test verifies that attempting to update a thread with invalid data (such as an empty title, or excessively long title/body strings) triggers validation errors and prevents updating actual thread data.
 *
 * Steps:
 *   1. Create a Board (required for the thread)
 *   2. Create a Member (thread author)
 *   3. Create a Thread (valid data under valid Board/Member)
 *   4. Attempt to update the thread with:
 *      - Empty title string (should fail)
 *      - Excessively long title string (should fail)
 *      - Excessively long body string (should fail)
 *   5. Confirm that after invalid updates, thread content is unchanged.
 */
export async function test_api_discussionboard_test_update_thread_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create board (for thread)
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.alphabets(8),
      code: RandomGenerator.alphaNumeric(12),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    },
  });
  typia.assert(board);

  // 2. Create thread author (member)
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(64),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 3. Create thread (valid content)
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1, 1),
      body: RandomGenerator.paragraph()(3, 10),
    },
  });
  typia.assert(thread);

  // 4a. Attempt update with empty title (invalid, should error)
  await TestValidator.error("empty title is not allowed")(() =>
    api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: ""
      } satisfies IDiscussionboardThreads.IUpdate,
    })
  );

  // 4b. Attempt update with excessively long title (invalid, should error)
  await TestValidator.error("excessively long title is not allowed")(() =>
    api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        title: "T".repeat(10000),
      } satisfies IDiscussionboardThreads.IUpdate,
    })
  );

  // 4c. Attempt update with excessively long body (invalid, should error)
  await TestValidator.error("excessively long body is not allowed")(() =>
    api.functional.discussionboard.threads.update(connection, {
      id: thread.id,
      body: {
        body: "B".repeat(100000),
      } satisfies IDiscussionboardThreads.IUpdate,
    })
  );

  // 5. Confirm thread remains unchanged (should still have original values)
  // (Since no GET API, use update with empty body as a no-op to receive latest thread)
  const reloaded = await api.functional.discussionboard.threads.update(connection, {
    id: thread.id,
    body: {} as IDiscussionboardThreads.IUpdate,
  });
  typia.assert(reloaded);
  TestValidator.equals("thread title unchanged after invalid updates")(reloaded.title)(thread.title);
  TestValidator.equals("thread body unchanged after invalid updates")(reloaded.body)(thread.body);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { ISoftDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/ISoftDeleteConfirmation";

/**
 * Validate soft-deleting a thread by its id.
 *
 * Business context:
 * Soft-deletion means marking the thread as deleted by setting its deleted_at timestamp, instead of actually erasing it from the database. This ensures data auditability and potential restoration, which is important for compliance and history in community forums.
 *
 * Test Process:
 * 1. Create a board (required for thread creation)
 * 2. Create a member (author of the thread)
 * 3. Create a thread under the board, authored by the member
 * 4. Call DELETE /discussionboard/threads/{id} to soft-delete the thread
 * 5. Confirm that the response returns the correct id and soft_deleted: true
 * 6. (Post-delete check logic omitted: no GET API is present to fetch the thread and inspect deleted_at)
 */
export async function test_api_discussionboard_test_soft_delete_thread_success(
  connection: api.IConnection,
) {
  // 1. Create a board
  const board = await api.functional.discussionboard.boards.create(
    connection,
    {
      body: {
        discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
        name: RandomGenerator.paragraph()(2),
        code: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph()(1),
        is_active: true,
        is_visible: true,
      } satisfies IBoard.ICreate,
    },
  );
  typia.assert(board);

  // 2. Create a member (author)
  const member = await api.functional.discussionboard.members.create(
    connection,
    {
      body: {
        username: RandomGenerator.alphaNumeric(10),
        email: typia.random<string & tags.Format<"email">>(),
        hashed_password: RandomGenerator.alphaNumeric(32),
        role: "member",
        is_active: true,
      } satisfies IDiscussionboardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create a thread authored by the member in the board
  const thread = await api.functional.discussionboard.threads.create(
    connection,
    {
      body: {
        board_id: board.id,
        author_member_id: member.id,
        title: RandomGenerator.paragraph()(1),
        body: RandomGenerator.content()(1)(3),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 4. Soft-delete the thread by id
  const deletion = await api.functional.discussionboard.threads.erase(
    connection,
    { id: thread.id },
  );
  typia.assert(deletion);

  // 5. Check correct thread id and soft_deleted:true in response
  TestValidator.equals("soft-delete id matches")(deletion.id)(thread.id);
  TestValidator.equals("soft_deleted success")(deletion.soft_deleted)(true);
}

