import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { ISoftDeleteConfirmation } from "@ORGANIZATION/PROJECT-api/lib/structures/ISoftDeleteConfirmation";

/**
 * Test repeated soft deletion of an already soft-deleted thread to ensure idempotency and correct error-handling.
 *
 * This test follows the flow:
 * 1. Create the discussion board to host the thread. (board dependency)
 * 2. Register a new member who will be the thread's author. (member dependency)
 * 3. Create a new thread under the board, authored by the member. (thread dependency)
 * 4. Soft-delete (erase) the thread (first logical delete).
 * 5. Attempt to soft-delete (erase) the same thread again.
 * 6. Validate the outcome:
 *   - The second delete call should either succeed idempotently (with soft_deleted true or false), 
 *     or result in an error according to the platform's rules. 
 *   - The response must match the ISoftDeleteConfirmation contract.
 *
 * Steps 1-4 are prerequisites; step 5-6 perform the core test scenario.
 */
export async function test_api_discussionboard_test_soft_delete_already_deleted_thread(
  connection: api.IConnection
) {
  // 1. Create a discussion board.
  const boardCategoryId = typia.random<string & tags.Format<"uuid">>();
  const boardSectionId = typia.random<string & tags.Format<"uuid">>();
  const board = await api.functional.discussionboard.boards.create(connection, {
    body: {
      discussionboard_board_category_id: boardCategoryId,
      discussionboard_section_id: boardSectionId,
      name: RandomGenerator.paragraph()(1),
      code: RandomGenerator.alphaNumeric(8),
      description: RandomGenerator.paragraph()(),
      is_active: true,
      is_visible: true,
    } satisfies IBoard.ICreate,
  });
  typia.assert(board);

  // 2. Create a member to be the thread's author.
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 3. Create a thread via POST /discussionboard/threads.
  const thread = await api.functional.discussionboard.threads.create(connection, {
    body: {
      board_id: board.id,
      author_member_id: member.id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Soft delete (erase) the thread (first time)
  const erase1 = await api.functional.discussionboard.threads.erase(connection, {
    id: thread.id,
  });
  typia.assert(erase1);
  TestValidator.equals("first erase id matches")(erase1.id)(thread.id);
  TestValidator.predicate("soft_deleted true after first erase")(erase1.soft_deleted === true);

  // 5. Attempt to soft-delete again (should be idempotent/no error)
  const erase2 = await api.functional.discussionboard.threads.erase(connection, {
    id: thread.id,
  });
  typia.assert(erase2);
  TestValidator.equals("second erase id matches")(erase2.id)(thread.id);
  // Accept either: still soft_deleted true, or contractually false
  TestValidator.predicate("second erase is still idempotent soft_deleted true or false")(typeof erase2.soft_deleted === "boolean");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";
import type { IPageIdiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_post_votes";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 투표 목록을 유효한 필터 조건, 정렬, 페이지네이션을 적용하여 조회하는 기능을 검증합니다.
 *
 * 이 테스트는 다음과 같은 현실적인 워크플로우를 따릅니다:
 *
 * 1. 투표를 생성할 회원을 등록한다.
 * 2. 회원이 속한 게시글을 생성한다.
 * 3. 해당 회원이 해당 게시글에 투표를 한번 생성한다.
 * 4. 게시글 ID, 회원 ID, 투표 타입(1, -1, 0), 생성 시각(created_at 범위)로 필터를 사용하여 투표 목록을 조회한다.
 * 5. 반환된 투표들의 각 항목이 필터 조건을 모두 만족하는지 확인한다.
 * 6. 페이지네이션 정보가 응답에 포함되어 있고, 정상적으로 값들이 셋팅되는지 검증한다.
 */
export async function test_api_discussionboard_test_list_post_votes_with_valid_filters(
  connection: api.IConnection,
) {
  // 1. 회원 등록
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphabets(10);
  const memberResp = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(memberResp);

  // 2. 게시글 생성 (thread/board uuid 임의 생성)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const postResp = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: memberResp.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()(1)(1),
    },
  });
  typia.assert(postResp);

  // 3. 게시글에 투표 생성
  const now = new Date();
  const voteCreatedAt = now.toISOString();
  const VOTE_TYPE = 1; // upvote
  const voteResp = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: postResp.id,
      discussionboard_member_id: memberResp.id,
      vote_type: VOTE_TYPE,
      created_at: voteCreatedAt,
    },
  });
  typia.assert(voteResp);

  // 4. 투표 목록 필터(게시글ID, 회원ID, vote_type, created_at)를 활용한 조회
  const votesPage = await api.functional.discussionboard.postVotes.index(connection, {
    body: {
      discussionboard_post_id: postResp.id,
      discussionboard_member_id: memberResp.id,
      vote_type: VOTE_TYPE,
      created_at: voteCreatedAt,
    },
  });
  typia.assert(votesPage);

  // 5. 반환된 각 투표가 조건을 정확히 만족하는지 검증
  for (const v of votesPage.data) {
    TestValidator.equals("게시글 아이디 일치")(v.discussionboard_post_id)(postResp.id);
    TestValidator.equals("회원 아이디 일치")(v.discussionboard_member_id)(memberResp.id);
    TestValidator.equals("투표 유형 일치")(v.vote_type)(VOTE_TYPE);
    TestValidator.equals("생성일시 일치")(v.created_at)(voteCreatedAt);
  }
  // 6. 페이지네이션 메타 검증
  const pagination = votesPage.pagination;
  TestValidator.predicate("페이지네이션 현재 page가 1 이상")(pagination.current >= 1);
  TestValidator.predicate("페이지네이션 limit이 1 이상")(pagination.limit >= 1);
  TestValidator.predicate("페이지네이션 records가 1 이상")(pagination.records >= 1);
  TestValidator.predicate("페이지네이션 pages가 1 이상")(pagination.pages >= 1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";
import type { IPageIdiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIdiscussionboard_post_votes";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test to verify searching post votes with filters that match no results.
 *
 * This test validates that searching discussionboard_post_votes with filters for nonexistent post or member IDs
 * returns an empty result set and correct pagination metadata. This is crucial for confirming correct zero-result
 * handling in search APIs and absence-handling by client code.
 *
 * Workflow:
 * 1. Generate guaranteed-nonexistent post and member IDs using typia.random (not previously inserted)
 * 2. Call the postVotes.index API with each filter (by post, by member)
 * 3. Assert data arrays are empty, and pagination.count is zero
 * 4. Confirm pagination metadata (current page, limit, etc.) are reasonable
 */
export async function test_api_discussionboard_test_list_post_votes_with_no_matching_results(
  connection: api.IConnection,
) {
  // 1. Generate random, nonexistent post and member IDs (assumed not present in DB)
  const nonexistent_post_id = typia.random<string & tags.Format<"uuid">>();
  const nonexistent_member_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Search by nonexistent post ID
  const result_by_post = await api.functional.discussionboard.postVotes.index(connection, {
    body: { discussionboard_post_id: nonexistent_post_id },
  });
  typia.assert(result_by_post);
  TestValidator.equals("no results with nonexistent post_id")(result_by_post.data)([]);
  TestValidator.equals("records is zero with nonexistent post_id")(result_by_post.pagination.records)(0);
  TestValidator.predicate("pagination: current page is 1")(result_by_post.pagination.current === 1);
  TestValidator.predicate("pagination: limit is positive")(result_by_post.pagination.limit > 0);

  // 3. Search by nonexistent member ID
  const result_by_member = await api.functional.discussionboard.postVotes.index(connection, {
    body: { discussionboard_member_id: nonexistent_member_id },
  });
  typia.assert(result_by_member);
  TestValidator.equals("no results with nonexistent member_id")(result_by_member.data)([]);
  TestValidator.equals("records is zero with nonexistent member_id")(result_by_member.pagination.records)(0);
  TestValidator.predicate("pagination: current page is 1")(result_by_member.pagination.current === 1);
  TestValidator.predicate("pagination: limit is positive")(result_by_member.pagination.limit > 0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Validate successful retrieval of a post vote by its existing ID.
 *
 * This test covers the workflow for capturing and reading a post vote in the discussion board system.
 * It performs the following sequence:
 * 1. Registers a new member with realistic details for voting.
 * 2. Creates a post authored by that member using valid associations.
 * 3. Casts a vote by the registered member on the created post using the valid vote type and timestamp.
 * 4. Retrieves the vote just created by its unique ID using the `GET /discussionboard/postVotes/{id}` endpoint.
 * 5. Validates that all returned vote details (IDs, type, and timestamps) match what was used when creating the vote.
 */
export async function test_api_discussionboard_test_get_post_vote_by_existing_id(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(14),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Create a post authored by the new member
  const postInput: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Cast a vote on the post by the member
  const now = new Date().toISOString();
  const voteInput: Idiscussionboard_post_votes.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: 1,
    created_at: now,
  };
  const vote = await api.functional.discussionboard.postVotes.create(connection, { body: voteInput });
  typia.assert(vote);

  // 4. Retrieve the vote by ID
  const fetchedVote = await api.functional.discussionboard.postVotes.at(connection, { id: vote.id });
  typia.assert(fetchedVote);

  // 5. Validate returned data matches creation
  TestValidator.equals("vote id")(fetchedVote.id)(vote.id);
  TestValidator.equals("post id")(fetchedVote.discussionboard_post_id)(voteInput.discussionboard_post_id);
  TestValidator.equals("member id")(fetchedVote.discussionboard_member_id)(voteInput.discussionboard_member_id);
  TestValidator.equals("vote type")(fetchedVote.vote_type)(voteInput.vote_type);
  TestValidator.equals("created_at")(fetchedVote.created_at)(voteInput.created_at);
}

