import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Validates creation of a new post vote with correct member and post setup.
 *
 * - Ensures prerequisite entities (member, post) are properly created
 * - Casts a valid vote (vote_type ∈ {1, -1, 0}) on the post from the member
 * - Validates the returned vote record matches request data (member, post, vote_type, timestamp)
 * - Ensures full TypeScript type safety and required property coverage.
 *
 * Workflow:
 * 1. Register a new member for casting the vote
 * 2. Create a new board/thread/post that this vote will target
 * 3. Compose a payload for postVotes create using known member/post and legal vote_type
 * 4. Call API to create the vote, then verify response matches the request (excluding system-generated fields)
 */
export async function test_api_discussionboard_test_create_post_vote_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a discussion board member
  const memberReq: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberReq });
  typia.assert(member);

  // 2. Create a board/thread/post for voting
  // We'll need thread_id and board_id; for the test, generate random UUIDs
  const postReq: IDiscussionboardPost.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: member.id,
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()(1)(),
  };
  const post = await api.functional.discussionboard.posts.create(connection, { body: postReq });
  typia.assert(post);

  // 3. Compose a valid vote payload
  const voteTypes = [1, -1, 0];
  const vote_type: number = RandomGenerator.pick(voteTypes);
  const created_at = new Date().toISOString();
  const voteReq: Idiscussionboard_post_votes.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type,
    created_at,
  };

  // 4. Cast the vote and validate
  const vote = await api.functional.discussionboard.postVotes.create(connection, { body: voteReq });
  typia.assert(vote);

  // Business assertions - main fields match input
  TestValidator.equals("vote - post id")(vote.discussionboard_post_id)(voteReq.discussionboard_post_id);
  TestValidator.equals("vote - member id")(vote.discussionboard_member_id)(voteReq.discussionboard_member_id);
  TestValidator.equals("vote - vote_type")(vote.vote_type)(voteReq.vote_type);
  TestValidator.equals("vote - created_at")(vote.created_at)(voteReq.created_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
