import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Test post vote uniqueness constraint (duplicate vote error).
 *
 * This test ensures that the discussionboard_post_votes table correctly enforces
 * uniqueness on (discussionboard_post_id, discussionboard_member_id) pairs.
 *
 * Steps:
 * 1. Register a new member (provides valid user info).
 * 2. Create a post authored by the member (requires valid thread and board IDs).
 * 3. Cast an initial upvote for the post from this member.
 * 4. Attempt to cast a duplicate vote (same post, same member).
 * 5. Validate that the second attempt triggers a uniqueness error.
 */
export async function test_api_discussionboard_test_create_post_vote_duplicate_vote_error(
  connection: api.IConnection,
) {
  // 1. Register new member
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberUsername = RandomGenerator.alphabets(8);
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: memberUsername,
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(20), // Simulated hash
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a new post authored by the member
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const boardId = typia.random<string & tags.Format<"uuid">>();
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      discussionboard_member_id: member.id,
      discussionboard_board_id: boardId,
      title: RandomGenerator.paragraph()(2),
      body: RandomGenerator.content()(2)(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast the initial upvote
  const voteCreatedAt = new Date().toISOString();
  const votePayload: Idiscussionboard_post_votes.ICreate = {
    discussionboard_post_id: post.id,
    discussionboard_member_id: member.id,
    vote_type: 1, // Upvote
    created_at: voteCreatedAt,
  };
  const vote = await api.functional.discussionboard.postVotes.create(connection, {
    body: votePayload,
  });
  typia.assert(vote);

  // 4. Attempt to vote again with the same (post, member) pair
  await TestValidator.error("duplicate vote uniqueness constraint")(
    async () => {
      await api.functional.discussionboard.postVotes.create(connection, {
        body: votePayload,
      });
    },
  );
}

