import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_votes } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_votes";

/**
 * Test rejection of updating post vote with invalid vote_type and ensure no state change.
 *
 * Validates server schema enforcement on vote_type in update, and that state is
 * not modified on invalid requests.
 *
 * Steps:
 * 1. Register a new member for voting.
 * 2. Create a post for the member to vote on (supplying all required IDs).
 * 3. Cast a valid vote (upvote: vote_type = 1) on the post.
 * 4. Attempt to update the vote with an invalid vote_type (e.g., 5).
 *    - Confirm a schema (validation) error occurs.
 * 5. Confirm state is still the original by successfully updating with a valid value (e.g., neutral: vote_type = 0).
 */
export async function test_api_discussionboard_test_update_post_vote_with_invalid_vote_type_rejected(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a post for voting: thread, board with random UUIDs
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: member.id,
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(20),
      body: RandomGenerator.content()(80)(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 3. Cast a valid upvote
  const vote = await api.functional.discussionboard.postVotes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 1,
      created_at: new Date().toISOString(),
    } satisfies Idiscussionboard_post_votes.ICreate,
  });
  typia.assert(vote);

  // 4. Attempt invalid update (vote_type = 5, not allowed by schema)
  await TestValidator.error("rejects invalid vote_type update")(() =>
    api.functional.discussionboard.postVotes.update(connection, {
      id: vote.id,
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: member.id,
        vote_type: 5,
        created_at: vote.created_at,
      } as Idiscussionboard_post_votes.IUpdate,
    })
  );

  // 5. Confirm state is unchanged: update to a valid value (neutral)
  const updated = await api.functional.discussionboard.postVotes.update(connection, {
    id: vote.id,
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: member.id,
      vote_type: 0,
      created_at: vote.created_at,
    } satisfies Idiscussionboard_post_votes.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("vote_type is neutralized")(updated.vote_type)(0);
}

