/**
 * Validate retrieval of a specific post snapshot by id as an admin/moderator.
 *
 * This test ensures:
 * - A post is created as prerequisite entity for snapshot creation.
 * - A post snapshot is created, referencing the post and containing test content.
 * - The snapshot can be retrieved via GET by its unique id.
 * - The retrieved snapshot matches the originally created values: title, body, and exact timestamps.
 *
 * Steps:
 * 1. Create a discussion board post (IDiscussionboardPost).
 * 2. Create a post snapshot (Idiscussionboard_post_snapshots) using the new post's id and static mock values for all fields.
 * 3. Fetch the snapshot via GET by id.
 * 4. Assert all fields of the GET result match the returned snapshot from creation.
 */
export async function test_api_discussionboard_test_get_post_snapshot_details_when_exists(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board post (acts as the source entity for snapshot)
  const post: IDiscussionboardPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Snapshot Test Title",
      body: "Content to be snapshotted for e2e test."
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create a post snapshot using this post's id
  const now = new Date().toISOString();
  const snapshot: Idiscussionboard_post_snapshots = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: post.discussionboard_member_id, // simulate original author as editor
      title: "Snapshot Titled for e2e",
      body: "Snapshot body for matching on GET.",
      taken_at: now
    } satisfies Idiscussionboard_post_snapshots.ICreate,
  });
  typia.assert(snapshot);

  // 3. Fetch the snapshot by id
  const fetched: Idiscussionboard_post_snapshots = await api.functional.discussionboard.postSnapshots.at(connection, {
    id: snapshot.id
  });
  typia.assert(fetched);

  // 4. Assert all fields match exactly
  TestValidator.equals("post snapshot id")(fetched.id)(snapshot.id);
  TestValidator.equals("post ref")(fetched.discussionboard_post_id)(snapshot.discussionboard_post_id);
  TestValidator.equals("editor")(fetched.editor_member_id)(snapshot.editor_member_id);
  TestValidator.equals("title")(fetched.title)(snapshot.title);
  TestValidator.equals("body")(fetched.body)(snapshot.body);
  TestValidator.equals("taken_at")(fetched.taken_at)(snapshot.taken_at);
}

