import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_snapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_snapshots";

/**
 * Validate that a moderator or admin can create a post snapshot with all required and permitted schema fields.
 *
 * Business Purpose: Ensures correct behavior when moderators or administrators use the API to create a post snapshot for rollback/audit/version control. This test simulates a realistic workflow in which a post is authored, and then an authorized user captures a version snapshot with explicit audit metadata.
 *
 * Step-by-step process:
 * 1. Create prerequisite data for the snapshot by creating a valid post (with random UUIDs for all foreign keys and random content for title/body).
 * 2. Use the ID of the created post for the parent reference in the snapshot creation request.
 * 3. Craft a valid post snapshot payload with all required fields (including explicit editor_member_id and custom taken_at timestamp).
 * 4. Submit the request to create a post snapshot.
 * 5. Assert that all returned fields in the response align with the request payload and schema, i.e. discussionboard_post_id, title, body, editor_member_id, taken_at are correctly persisted, and that the entity provides the autogenerated id field.
 */
export async function test_api_discussionboard_test_create_post_snapshot_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create prerequisite post entity for snapshot
  const parentPost = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(parentPost);

  // 2. Build valid post snapshot request using post id
  const editorMemberId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const snapshotPayload = {
    discussionboard_post_id: parentPost.id,
    editor_member_id: editorMemberId,
    title: "[SNAPSHOT] " + parentPost.title,
    body: parentPost.body + "\n\n[Snapshot taken]",
    taken_at: new Date().toISOString() as string & tags.Format<"date-time">,
  } satisfies Idiscussionboard_post_snapshots.ICreate;

  // 3. Create snapshot
  const snapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: snapshotPayload,
  });
  typia.assert(snapshot);

  // 4. Assert persisted values match expectations
  TestValidator.equals("snapshot post reference")(snapshot.discussionboard_post_id)(parentPost.id);
  TestValidator.equals("snapshot editor_member_id")(snapshot.editor_member_id)(editorMemberId);
  TestValidator.equals("snapshot title")(snapshot.title)(snapshotPayload.title);
  TestValidator.equals("snapshot body")(snapshot.body)(snapshotPayload.body);
  TestValidator.equals("snapshot taken_at")(snapshot.taken_at)(snapshotPayload.taken_at);
  TestValidator.predicate("id is a valid UUID")(
    typeof snapshot.id === "string" && snapshot.id.length >= 10,
  );
}

