import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { Idiscussionboard_post_snapshots } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussionboard_post_snapshots";

/**
 * Validates that a moderator or admin can update discussion board post snapshot fields using only permitted attributes.
 *
 * This test scenario checks if updating title and body of a post snapshot (through PUT /discussionboard/postSnapshots/{id}) works as intended, strictly accepting only allowed schema fields. A post is created, then a snapshot linked to it; the snapshot is updated with new title/body (and no other fields). Response is checked for changes, field immutability, and schema satisfaction.
 *
 * Steps:
 * 1. Create a new post (to provide a valid post id for the snapshot).
 * 2. Create a post snapshot associated with the post (with initial title and body).
 * 3. Update only title and body fields of the snapshot, via PUT endpoint.
 * 4. Assert response has updated values and that unrelated fields remain unchanged.
 */
export async function test_api_discussionboard_test_update_post_snapshot_with_valid_changes(connection: api.IConnection) {
  // 1. Create a post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Original Post Title",
      body: "Initial post body.",
    } satisfies IDiscussionboardPost.ICreate,
  });
  typia.assert(post);

  // 2. Create a post snapshot for this post
  const initialSnapshot = await api.functional.discussionboard.postSnapshots.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      editor_member_id: typia.random<string & tags.Format<"uuid">>(),
      title: post.title,
      body: post.body,
      taken_at: new Date().toISOString(),
    } satisfies Idiscussionboard_post_snapshots.ICreate,
  });
  typia.assert(initialSnapshot);

  // 3. Update only allowed fields (title and body)
  const updateData: Idiscussionboard_post_snapshots.IUpdate = {
    title: "Updated Snapshot Title",
    body: "Updated snapshot body content.",
  };
  const updatedSnapshot = await api.functional.discussionboard.postSnapshots.update(connection, {
    id: initialSnapshot.id,
    body: updateData,
  });
  typia.assert(updatedSnapshot);

  // 4. Assert field changes and schema compliance
  TestValidator.equals("id unchanged")(updatedSnapshot.id)(initialSnapshot.id);
  TestValidator.equals("discussionboard_post_id unchanged")(updatedSnapshot.discussionboard_post_id)(initialSnapshot.discussionboard_post_id);
  if (initialSnapshot.editor_member_id !== undefined) {
    TestValidator.equals("editor_member_id unchanged")(updatedSnapshot.editor_member_id)(initialSnapshot.editor_member_id);
  }
  TestValidator.equals("title updated")(updatedSnapshot.title)(updateData.title);
  TestValidator.equals("body updated")(updatedSnapshot.body)(updateData.body);
  TestValidator.equals("taken_at unchanged")(updatedSnapshot.taken_at)(initialSnapshot.taken_at);
}

