/**
 * Validate rejection of updates to post snapshots when the payload is invalid (extra or missing fields).
 *
 * This test verifies that the PUT /discussionboard/postSnapshots/{id} endpoint properly rejects requests that contain invalid payloads:
 * - Extra fields not defined in the schema
 * - Missing all updatable fields (empty body)
 * - Presence of fields with incorrect types
 * The test expects 4XX validation errors, and confirms no snapshot mutation occurs.
 *
 * Workflow:
 * 1. Create a discussion post (dependency setup)
 * 2. Create a post snapshot for that post (dependency setup)
 * 3. Attempt updating the snapshot using a payload with extra/invalid fields
 *    a. Add an extra property not in the schema
 *    b. Use the correct schema fields but wrong type (e.g., title as number)
 *    c. Omit all properties (empty object)
 * 4. Validate that each update attempt is rejected with an error
 * 5. Optionally, confirm the snapshot remains unchanged by re-fetching or reading its value
 */
export async function test_api_discussionboard_test_update_post_snapshot_with_invalid_payload_rejected(
  connection: api.IConnection,
) {
  // 1. Create a valid discussionboard post
  const post = await api.functional.discussionboard.posts.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Valid Post for Snapshot Test",
      body: "Contents for snapshot testing."
    },
  });
