        name: "Alpha Forum",
        code: "alpha_forum",
        description: "Test board alpha.",
        is_active: true,
        is_visible: true,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[1],
        discussionboard_section_id: sections[0],
        name: "Beta Lounge",
        code: "beta_lounge",
        description: "Test board beta.",
        is_active: false,
        is_visible: true,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[0],
        discussionboard_section_id: sections[1],
        name: "Gamma Club",
        code: "gamma_club",
        description: "Test board gamma.",
        is_active: true,
        is_visible: false,
      }
    }),
    await api.functional.discussionboard.boards.create(connection, {
      body: {
        discussionboard_board_category_id: categories[1],
        discussionboard_section_id: sections[1],
        name: "Delta Room",
        code: "delta_room",
        description: "Test board delta.",
        is_active: false,
        is_visible: false,
      }
    }),
  ];
