import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IBoard";
import type { IPageIBoard } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIBoard";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing all discussion boards when no filter is provided.
 *
 * This test ensures the boards listing API returns all existing boards when
 * no filter criteria are applied. It creates several boards, invokes the
 * PATCH /discussionboard/boards endpoint without filters, then verifies that
 * every created board appears in the response. Handles multi-page results if
 * the dataset exceeds the default page size.
 *
 * Steps:
 * 1. Create multiple boards with randomized/diverse properties.
 * 2. List all boards using an empty filter.
 * 3. If pagination applies, fetch subsequent pages and combine all results.
 * 4. Assert all created boards exist in the complete listing.
 */
export async function test_api_discussionboard_test_list_boards_without_any_filter_returns_all(
  connection: api.IConnection,
) {
  // 1. Create multiple (e.g. 5) boards with distinct codes and names
  const createdBoards = await ArrayUtil.asyncRepeat(5)(async () => {
    const boardInput = {
      discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
      name: RandomGenerator.paragraph()(),
      code: RandomGenerator.alphaNumeric(12),
      description: Math.random() > 0.5 ? RandomGenerator.paragraph()() : null,
      is_active: Math.random() > 0.5,
      is_visible: Math.random() > 0.5,
    } satisfies IBoard.ICreate;
    const out = await api.functional.discussionboard.boards.create(connection, {
      body: boardInput,
    });
    typia.assert(out);
    return out;
  });

  // 2. List all boards, no search criteria
  const firstPage = await api.functional.discussionboard.boards.index(connection, {
    body: {},
  });
  typia.assert(firstPage);

  // 3. Aggregate results across pagination, if any
  let allBoards = [...firstPage.data];
  const seen = new Set<string>(allBoards.map((b) => b.id));
  let current = firstPage;
  while (allBoards.length < current.pagination.records) {
    const nextPageNumber = Math.floor(allBoards.length / current.pagination.limit) + 1;
    const nextPage = await api.functional.discussionboard.boards.index(connection, {
      body: { },
    });
    typia.assert(nextPage);
    for (const b of nextPage.data) {
      if (!seen.has(b.id)) {
        allBoards.push(b);
        seen.add(b.id);
      }
    }
    current = nextPage;
  }

  // 4. Verify all created boards are present
  for (const created of createdBoards) {
    if (!allBoards.some((b) => b.id === created.id)) {
      throw new Error(`Created board with id ${created.id} is missing from the paginated board listing.`);
    }
  }
}

