/**
 * Validate that board creation fails when required fields are missing.
 *
 * This comprehensive E2E test ensures the API returns a validation error when attempting to create
 * a board while omitting any of the required fields: name, code, discussionboard_board_category_id, or discussionboard_section_id.
 *
 * Steps:
 * 1. Prepare valid board creation input.
 * 2. For each required field, attempt creation with that field omitted.
 * 3. Assert via TestValidator.error that the API rejects the request.
 * 4. Confirm no board is created on invalid input (implicit, as no API lists boards in this test).
 *
 * This test assures the strong input validation and integrity of board creation business rules.
 */
export async function test_api_discussionboard_test_create_board_with_missing_required_field(
  connection: api.IConnection,
) {
  // Step 1: Prepare valid board creation input data
  const valid: IBoard.ICreate = {
    discussionboard_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: "Validation Test Board",
    code: `board_${typia.random<string>()}`,
    description: "A board for testing validation of required fields.",
    is_active: true,
    is_visible: true,
  };

  // Utility function: creates a copy of the object with specified key omitted
  const omit = <T extends object, K extends keyof T>(obj: T, key: K): Omit<T, K> => {
    const { [key]: _, ...rest } = obj;
    return rest as Omit<T, K>;
  };

  // Step 2: Test omitting each required field
  // 2.1 Omit 'name'
  await TestValidator.error("should not create board when 'name' is missing")(() =>
    api.functional.discussionboard.boards.create(connection, {
      body: omit(valid, "name") as IBoard.ICreate,
    })
  );

  // 2.2 Omit 'code'
  await TestValidator.error("should not create board when 'code' is missing")(() =>
    api.functional.discussionboard.boards.create(connection, {
      body: omit(valid, "code") as IBoard.ICreate,
    })
  );

  // 2.3 Omit 'discussionboard_board_category_id'
  await TestValidator.error("should not create board when 'discussionboard_board_category_id' is missing")(() =>
    api.functional.discussionboard.boards.create(connection, {
      body: omit(valid, "discussionboard_board_category_id") as IBoard.ICreate,
    })
  );

  // 2.4 Omit 'discussionboard_section_id'
  await TestValidator.error("should not create board when 'discussionboard_section_id' is missing")(() =>
    api.functional.discussionboard.boards.create(connection, {
      body: omit(valid, "discussionboard_section_id") as IBoard.ICreate,
    })
