/**
 * Validate updating an existing board entity in the discussion board system with new valid data.
 *
 * This test ensures the board update (PUT) endpoint properly overwrites only the specified updatable
 * fields, and leaves immutable and unspecified fields unchanged. It also confirms audit timestamps
 * update appropriately.
 *
 * Steps:
 * 1. Create an initial board with valid required properties (category/section/name/code/description/is_active/is_visible).
 * 2. Issue an update with a subset of modifiable fields (e.g., change name, visibility, description).
 * 3. Assert that the response has the changed values matching the update payload, and unchanged values are preserved from original.
 * 4. Confirm the updated board's updated_at timestamp is refreshed and strictly newer than the original created_at/updated_at.
 * 5. Confirm immutable fields (id, created_at) are unchanged and NOT overwritten.
 * 6. Optionally, re-fetch the board for double verification (if API supports fetch-by-id - if not, skip re-fetch).
 */
export async function test_api_discussionboard_test_update_board_with_valid_data(
  connection: api.IConnection,
) {
  // Step 1: Create an initial board with all mandatory and realistic properties
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const originalRequest: IBoard.ICreate = {
    discussionboard_board_category_id: categoryId,
    discussionboard_section_id: sectionId,
    name: "Initial Board Name",
    code: `initial_code_${RandomGenerator.alphaNumeric(6)}`,
    description: "Board pre-update",
    is_active: true,
    is_visible: true,
  };
  const original: IBoard = await api.functional.discussionboard.boards.create(
    connection,
    { body: originalRequest }
  );
  typia.assert(original);

  // Step 2: Prepare an update with new values for a subset of updatable fields
  const updatedFields: IBoard.IUpdate = {
    name: "Renamed Board",
    description: "Description after update",
    is_visible: false,
  };
  const updated: IBoard = await api.functional.discussionboard.boards.update(
    connection,
    {
      id: original.id,
      body: updatedFields,
    }
  );
  typia.assert(updated);

  // Step 3: Assert the changed values match the update, other values preserved
  TestValidator.equals("updated name")(updated.name)(updatedFields.name);
  TestValidator.equals("updated description")(updated.description)(updatedFields.description);
  TestValidator.equals("updated is_visible")(updated.is_visible)(updatedFields.is_visible);

  TestValidator.equals("category_id unaffected")(updated.discussionboard_board_category_id)(original.discussionboard_board_category_id);
  TestValidator.equals("section_id unaffected")(updated.discussionboard_section_id)(original.discussionboard_section_id);
  TestValidator.equals("code unaffected")(updated.code)(original.code);
  TestValidator.equals("is_active unaffected")(updated.is_active)(original.is_active);
  TestValidator.equals("id unchanged")(updated.id)(original.id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(original.created_at);

  // Step 4: Timestamp updated_at should be newer than the prior value
  TestValidator.predicate("updated_at is newer")(
    new Date(updated.updated_at).getTime() > new Date(original.updated_at).getTime()
  );

  // Step 5: Optionally re-fetch for double-check (assume update returns full entity)
  // (If GET /discussionboard/boards/:id existed, would use here, but left as-is per provided SDK.)
}

