import type { IDiscussionboardDataErasureRequests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequests";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * Validate retrieval of a single data erasure request by its valid UUID.
 *
 * This test ensures that an existing data erasure request can be retrieved by its id.
 * The returned record's fields are validated for presence and equality to source values so admins
 * or designated staff can review and verify the request details accurately and securely.
 *
 * Test flow:
 * 1. Create a member account (dependency for generating a legitimate data erasure request)
 * 2. Create a data erasure request as that member
 * 3. Fetch (GET) the data erasure request by its unique id
 * 4. Confirm all schema-defined fields are present, correctly populated, and match the original request
 */
export async function test_api_discussionboard_dataErasureRequests_test_get_data_erasure_request_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a member account
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    },
  });
  typia.assert(member);

  // 2. Create a data erasure request for this member
  const request = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: {
      discussionboard_member_id: member.id,
    },
  });
  typia.assert(request);

  // 3. Retrieve the data erasure request by id
  const fetched = await api.functional.discussionboard.dataErasureRequests.at(connection, {
    id: request.id,
  });
  typia.assert(fetched);

  // 4. Validate all core fields for presence and content correctness
  // The returned type is IDiscussionboardDataErasureRequests,
  // while the create API returns IDiscussionboardDataErasureRequest,
  // but the field names and types are aligned for assertion and equality.
  TestValidator.equals("id matches")(fetched.id)(request.id);
  TestValidator.equals("member id matches")(fetched.discussionboard_member_id)(member.id);
  TestValidator.equals("status is pending")(fetched.status)(request.status);
  TestValidator.equals("requested_at matches")(fetched.requested_at)(request.requested_at);
  TestValidator.equals("reviewed_at matches")(fetched.reviewed_at ?? null)(request.reviewed_at ?? null);
  TestValidator.equals("completed_at matches")(fetched.completed_at ?? null)(request.completed_at ?? null);
  TestValidator.equals("admin_remark matches")(fetched.admin_remark ?? null)(request.admin_remark ?? null);
}

