import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * E2E test for submitting a data erasure request as a legitimate discussion board member.
 *
 * Validates that:
 * - Only authenticated/registered members can submit new requests
 * - The server creates a new erasure request row with status 'pending', assigns an id, and sets requested_at
 * - Fields reviewed_at, completed_at, and admin_remark are not set (null or undefined) on creation
 * - The created record contains only schema-defined fields and blocks extraneous content
 * - When a member already has an open/pending request, a duplicate submission is rejected
 *
 * Steps:
 * 1. Register a new discussion board member (dependency)
 * 2. Submit a data erasure request as that member
 * 3. Validate server response for correct status, audit fields, and schema-compliance
 * 4. Attempt a duplicate erasure request for the same member (should fail)
 *
 * Note: Negative test for unauthenticated access is omitted since API requires only member id and does not support session-based auth or token mechanisms in the supplied SDK.
 */
export async function test_api_discussionboard_test_create_data_erasure_request_with_valid_member(
  connection: api.IConnection,
) {
  // 1. Register a new member for erasure request scenario
  const email = typia.random<string & tags.Format<"email">>();
  const username = RandomGenerator.alphaNumeric(12);
  const hashed_password = RandomGenerator.alphaNumeric(32);
  const role = "member";

  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username,
      email,
      hashed_password,
      role,
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);
  TestValidator.equals("member.role is 'member'")(member.role)(role);
  TestValidator.equals("is_active is true")(member.is_active)(true);

  // 2. Submit a data erasure request with that member's ID
  const erasureRequest = await api.functional.discussionboard.dataErasureRequests.create(
    connection,
    {
      body: {
        discussionboard_member_id: member.id,
      } satisfies IDiscussionboardDataErasureRequest.ICreate,
    },
  );
  typia.assert(erasureRequest);

  // 3. Validate properties set by the server according to the privacy workflow
  TestValidator.equals("discussionboard_member_id same as member.id")(
    erasureRequest.discussionboard_member_id
  )(member.id);
  TestValidator.equals("status should be 'pending'")(erasureRequest.status)("pending");
  TestValidator.equals("requested_at is an ISO string")(
    typeof erasureRequest.requested_at
  )("string");
  TestValidator.equals("reviewed_at is null or undefined")(
    erasureRequest.reviewed_at ?? null
  )(null);
  TestValidator.equals("completed_at is null or undefined")(
    erasureRequest.completed_at ?? null
  )(null);
  TestValidator.equals("admin_remark is null or undefined")(
    erasureRequest.admin_remark ?? null
  )(null);

  // Check assigned properties: no extra/unknown fields
  const expectedKeys = [
    "id",
    "discussionboard_member_id",
    "status",
    "requested_at",
    "reviewed_at",
    "completed_at",
    "admin_remark",
  ];
  TestValidator.equals("Output only has schema-defined fields")(
    Object.keys(erasureRequest).sort().join(",")
  )(expectedKeys.sort().join(","));

  // 4. Attempt to submit another request with the same member (should fail)
  await TestValidator.error("Duplicate erasure request should be rejected")(
    async () => {
      await api.functional.discussionboard.dataErasureRequests.create(connection, {
        body: { discussionboard_member_id: member.id } satisfies IDiscussionboardDataErasureRequest.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * Validates enforcement of single open/pending erasure request per member in the discussion board system.
 *
 * Business context: For regulatory compliance and proper privacy management, a member must not have more than one 'pending' (open) data erasure request at any given time. The platform should prevent submission of new requests when one already exists in such a status. This E2E test verifies API constraint enforcement.
 *
 * Steps:
 * 1. Create a new member account (provides a unique, isolated test member).
 * 2. As that member, submit an initial data erasure request – this should succeed and status should be 'pending'.
 * 3. Immediately attempt to submit a second data erasure request for the same member (with status still 'pending').
 * 4. Confirm the API rejects the second request (throws error). The reason should be a business or validation error (no need to check exact error message).
 * 5. Final cleanup or further steps are omitted (as the member and requests are isolated for this test).
 */
export async function test_api_discussionboard_test_create_data_erasure_request_when_already_pending(
  connection: api.IConnection,
) {
  // 1. Create a new member
  const memberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphabets(16),
    role: "member",
    is_active: true,
  };
  const member = await api.functional.discussionboard.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Submit first data erasure request (should succeed, status should be 'pending')
  const firstRequest = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: { discussionboard_member_id: member.id } satisfies IDiscussionboardDataErasureRequest.ICreate,
  });
  typia.assert(firstRequest);
  TestValidator.equals("first erasure request member ref")(firstRequest.discussionboard_member_id)(member.id);
  TestValidator.equals("first erasure request status")(firstRequest.status)("pending");

  // 3. Attempt to submit a second data erasure request for the same member
  // 4. Expect an error: API should reject due to existing pending request
  await TestValidator.error("system should reject duplicate open data erasure requests")(
    () => api.functional.discussionboard.dataErasureRequests.create(connection, {
      body: { discussionboard_member_id: member.id } satisfies IDiscussionboardDataErasureRequest.ICreate,
    })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * Test data erasure request update workflow by admin.
 *
 * Tests the ability of an admin to update 'status', 'reviewed_at', 'completed_at', and 'admin_remark' on a data erasure request,
 * following strict workflow transitions.
 *
 * Steps:
 * 1. Create a test member
 * 2. Submit a data erasure request (should default to 'pending')
 * 3. Approve the request as admin (status → 'approved', set reviewed_at, admin_remark)
 * 4. Mark the request as completed (status → 'completed', set completed_at, update admin_remark)
 * 5. Assert that only schema fields changed, immutable fields remain fixed
 *
 * Business context:
 * - Ensures that the update API enforces schema constraints (only updatable fields modifiable)
 * - Validates transition rules for status and timestamps (no skipping or reversal)
 * - Ensures auditability (timestamps and remarks reflect proper workflow)
 * - Ensures compliance with privacy/audit requirements (no unauthorized/untracked actions)
 */
export async function test_api_discussionboard_dataErasureRequests_test_update_data_erasure_request_status_by_admin(connection: api.IConnection) {
  // 1. Create a test member who will request data erasure
  const member = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(10),
      email: typia.random<string & tags.Format<'email'>>(),
      hashed_password: RandomGenerator.alphabets(16),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a data erasure request for that member
  const erasure = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: {
      discussionboard_member_id: member.id,
    } satisfies IDiscussionboardDataErasureRequest.ICreate,
  });
  typia.assert(erasure);
  TestValidator.equals("Initial status should be pending")(erasure.status)("pending");
  TestValidator.equals("Correct member referenced")(erasure.discussionboard_member_id)(member.id);
  TestValidator.predicate("No reviewed_at at creation")(erasure.reviewed_at === null || erasure.reviewed_at === undefined);
  TestValidator.predicate("No completed_at at creation")(erasure.completed_at === null || erasure.completed_at === undefined);
  TestValidator.predicate("No admin_remark at creation")(erasure.admin_remark === null || erasure.admin_remark === undefined);

  // 3. Approve the request: update status to 'approved', set reviewed_at and admin_remark
  const reviewedAt = new Date().toISOString();
  const remark1 = "Request reviewed and approved.";
  const approved = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: erasure.id,
    body: {
      status: "approved",
      reviewed_at: reviewedAt,
      admin_remark: remark1,
    } satisfies IDiscussionboardDataErasureRequest.IUpdate,
  });
  typia.assert(approved);
  TestValidator.equals("Status updated to approved")(approved.status)("approved");
  TestValidator.equals("reviewed_at set")(approved.reviewed_at)(reviewedAt);
  TestValidator.equals("admin_remark set")(approved.admin_remark)(remark1);

  // 4. Mark as completed: status to 'completed', completed_at timestamp, update admin_remark
  const completedAt = new Date(Date.now() + 60 * 1000).toISOString(); // +1 minute
  const remark2 = "Erasure process finalized.";
  const completed = await api.functional.discussionboard.dataErasureRequests.update(connection, {
    id: erasure.id,
    body: {
      status: "completed",
      completed_at: completedAt,
      admin_remark: remark2,
    } satisfies IDiscussionboardDataErasureRequest.IUpdate,
  });
  typia.assert(completed);
  TestValidator.equals("Status updated to completed")(completed.status)("completed");
  TestValidator.equals("completed_at set")(completed.completed_at)(completedAt);
  TestValidator.equals("admin_remark updated")(completed.admin_remark)(remark2);

  // 5. Immutable fields unchanged
  TestValidator.equals("Request id unchanged")(completed.id)(erasure.id);
  TestValidator.equals("Member id unchanged")(completed.discussionboard_member_id)(member.id);
  TestValidator.equals("requested_at unchanged")(completed.requested_at)(erasure.requested_at);

  // Edge Case: If testing reversion or invalid transitions was supported by API, attempt here (currently not implemented).
}

