import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IDiscussionboardDataErasureRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardDataErasureRequest";

/**
 * Test the hard (permanent) deletion of a data erasure request by id by an admin or moderator.
 *
 * Verifies:
 *  - Only one id parameter is needed to delete.
 *  - Record is irrecoverably deleted (cannot re-read it after deletion).
 *  - Deletion does NOT cascade to member (the regular member remains).
 *
 * Steps:
 *   1. Create a regular member that will be the subject of the erasure request.
 *   2. Create a data erasure request for the member.
 *   3. Delete the data erasure request by id.
 *   4. Confirm the request is irreversibly deleted (re-fetch should fail).
 *   5. Confirm that the member record still exists (not deleted/cascaded).
 */
export async function test_api_discussionboard_test_delete_data_erasure_request_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a regular member to be subject of erasure request
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create a data erasure request for this member
  const req: IDiscussionboardDataErasureRequest = await api.functional.discussionboard.dataErasureRequests.create(connection, {
    body: {
      discussionboard_member_id: member.id,
    } satisfies IDiscussionboardDataErasureRequest.ICreate,
  });
  typia.assert(req);

  // 3. Delete the erasure request by id
  await api.functional.discussionboard.dataErasureRequests.erase(connection, {
    id: req.id,
  });

  // 4. Attempt to fetch again, should fail
  await TestValidator.error("Should not be able to reload deleted data erasure request")(
    () => (api.functional.discussionboard.dataErasureRequests as any).at?.(connection, { id: req.id })
  );

  // 5. Confirm member record still exists
  const reloadedMember: IDiscussionboardMember = await (api.functional.discussionboard.members as any).at?.(connection, { id: member.id });
  typia.assert(reloadedMember);
  TestValidator.equals("Member unchanged")(reloadedMember.id)(member.id);
}

