import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardActivityLog";

/**
 * 테스트 목적: 단일 활동 로그(id 기반) 조회 기능 검증
 * 
 * 활동 로그 상세 조회 API의 정상 케이스(존재하는 id)에 대해, 스키마 내 모든 필드가 정상적으로 반환되는지 확인한다. 오류 케이스에서는 존재하지 않거나 삭제된 id로 요청 시 404(혹은 적절한 미존재 에러)가 발생하는지 검증한다.
 *
 * 비즈니스 맥락:
 * - 활동 로그는 시스템 또는 멤버 단위로 생성되는 이벤트 기록이다.
 * - record의 id는 UUID로 관리되고, 생성 시 자동 할당된다.
 * - soft/hard delete 없이 완전 삭제만 허용된다(이 테스트에서는 "이미 삭제" 시나리오는 omit).
 *
 * 테스트 단계:
 * 1. 사전: activity log 생성 API로 신규 활동 로그 레코드를 만든다(ID 확보 목적). 
 * 2. 정상: 생성한 활동 로그의 id로 단건 상세 조회 API 호출 → 반환 스키마 각 필드가 생성 데이터와 일치하는지 확인
 * 3. 오류: 무작위 또는 존재하지 않는 UUID로 요청 → 404(혹은 not-found) 에러 발생을 검증
 *
 * 권한:
 * - 모든 역할이 조회 가능한 엔드포인트라면 따로 인증 변환은 omit. 역할 제한 시엔 인증 분기 추가
 */
export async function test_api_discussionboard_activityLogs_test_get_single_activity_log_by_valid_and_invalid_id(
  connection: api.IConnection,
) {
  // 1. 활동 로그 생성
  const createInput: IDiscussionboardActivityLog.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
    event_timestamp: typia.random<string & tags.Format<"date-time">>(),
    event_type: "test_event",
    event_metadata: JSON.stringify({ foo: "bar" }),
  };
  const created = await api.functional.discussionboard.activityLogs.create(connection, { body: createInput });
  typia.assert(created);

  // 2. 정상 케이스: 생성한 id로 상세 조회
  const output = await api.functional.discussionboard.activityLogs.at(connection, { id: created.id });
  typia.assert(output);
  // id 일치, 주요 필드 값 확인
  TestValidator.equals("id 일치")(output.id)(created.id);
  TestValidator.equals("member id")(output.discussionboard_member_id)(createInput.discussionboard_member_id);
  TestValidator.equals("board id")(output.discussionboard_board_id)(createInput.discussionboard_board_id);
  TestValidator.equals("thread id")(output.discussionboard_thread_id)(createInput.discussionboard_thread_id);
  TestValidator.equals("post id")(output.discussionboard_post_id)(createInput.discussionboard_post_id);
  TestValidator.equals("comment id")(output.discussionboard_comment_id)(createInput.discussionboard_comment_id);
  TestValidator.equals("event_timestamp")(output.event_timestamp)(createInput.event_timestamp);
  TestValidator.equals("event_type")(output.event_type)(createInput.event_type);
  TestValidator.equals("event_metadata")(output.event_metadata)(createInput.event_metadata);

