 *
 * This E2E test validates the correct behavior and robustness of the engagement metric update API. It ensures not only successful full-field updates but also robustness against invalid operations and proper enforcement of business rules for the model. Steps:
 *
 * 1. Create a baseline engagement metric to update.
 * 2. Update all updatable fields (counts and associations) with new valid data and confirm changes.
 * 3. Edge: update associations to null, and verify nullability is respected.
 * 4. Try updating a non-existent id; verify not-found handling.
 * 5. Attempt updates with business-logic invalid negative counts and check they are rejected.
 */
export async function test_api_discussionboard_engagementMetrics_test_update_engagement_metric_fields_and_handle_errors(
  connection: api.IConnection,
) {
  // 1. Create a metric for update test
  const created = await api.functional.discussionboard.engagementMetrics.create(
    connection,
    {
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
