        comments_created_count: 5,
        votes_cast_count: 3,
      } satisfies IDiscussionboardEngagementMetric.ICreate,
    },
  );
  typia.assert(created);

  // 2. Update all updatable fields with new valid replacements
  const updated = await api.functional.discussionboard.engagementMetrics.update(
    connection,
    {
      id: created.id,
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 20,
        comments_created_count: 8,
        votes_cast_count: 4,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("update applied: post count")(updated.posts_created_count)(20);
  TestValidator.equals("update applied: comments")(updated.comments_created_count)(8);
  TestValidator.equals("update applied: votes")(updated.votes_cast_count)(4);

  // 3. Edge: update associations to null and verify API accepts nulls
  const nullFields = await api.functional.discussionboard.engagementMetrics.update(
    connection,
    {
      id: created.id,
      body: {
        discussionboard_member_id: null,
        discussionboard_board_id: null,
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 7,
        comments_created_count: 2,
        votes_cast_count: 1,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    },
  );
