  TestValidator.equals("member is null")(nullFields.discussionboard_member_id)(null);
  TestValidator.equals("board is null")(nullFields.discussionboard_board_id)(null);

  // 4. Update to a non-existent id (not found)
  await TestValidator.error("update not found")(() =>
    api.functional.discussionboard.engagementMetrics.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
        discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
        engagement_date: typia.random<string & tags.Format<"date-time">>(),
        posts_created_count: 22,
        comments_created_count: 3,
        votes_cast_count: 5,
      } satisfies IDiscussionboardEngagementMetric.IUpdate,
    })
  );

  // 5. Updates with business logic invalid negative counts
  for (const field of [
    "posts_created_count",
    "comments_created_count",
    "votes_cast_count",
  ]) {
    const next: IDiscussionboardEngagementMetric.IUpdate = {
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_board_id: typia.random<string & tags.Format<"uuid">>(),
      engagement_date: typia.random<string & tags.Format<"date-time">>(),
      posts_created_count: 1,
      comments_created_count: 2,
      votes_cast_count: 3,
    };
    (next as any)[field] = -123;
    await TestValidator.error(`negative value - ${field}`)(() =>
      api.functional.discussionboard.engagementMetrics.update(connection, {
        id: created.id,
        body: next,
      })
    );
  }
}

