/**
 * Validate paginated, filtered retrieval of notification preferences.
 *
 * This test ensures that the PATCH endpoint for /discussionboard/notificationPreferences correctly returns a paginated and filtered list based on various search criteria. It first creates multiple notification preference records, spanning different members and template codes, each with different combinations of channel booleans (email_enabled, inapp_enabled, browser_enabled). The test then executes the index method with multiple combinations of filters – by member, by code, by notification channel, and with differing page limits. It verifies that:
 *
 * 1. Filtering by each individual field (discussionboard_member_id/code/email_enabled/inapp_enabled/browser_enabled) only returns matching records.
 * 2. Pagination (limit/page) works correctly, with accurate page meta information and data slice.
 * 3. No deleted records exist in the result set (by design, as all are active by default).
 *
 * Steps:
 * 1. Create multiple notification preference records with distinct members, codes, and combinations of notification flags.
 * 2. For each filterable field:
 *    - Query with that filter alone and verify only matching records are in results.
 * 3. For pagination:
 *    - Query with page=1, limit=2 and verify two results per page and correct meta info.
 *    - Query page=2, limit=2 and verify correct continued slice.
 */
export async function test_api_discussionboard_test_list_notification_preferences_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create dataset: several members, codes, flag combinations
  const member1 = typia.random<string & tags.Format<"uuid">>();
  const member2 = typia.random<string & tags.Format<"uuid">>();
  const codes = [
    "reply",
    "mention",
    "announcement",
  ];
  const records: IDiscussionboardNotificationPreferences[] = [];
  for (const memberId of [member1, member2]) {
    for (const code of codes) {
      for (const combo of [
        [true, false, false],
        [false, true, false],
        [false, false, true],
        [true, true, true],
      ]) {
        const rec = await api.functional.discussionboard.notificationPreferences.create(
          connection,
          {
            body: {
              discussionboard_member_id: memberId,
              code,
              email_enabled: combo[0],
              inapp_enabled: combo[1],
              browser_enabled: combo[2],
            } satisfies IDiscussionboardNotificationPreferences.ICreate,
          },
        );
        typia.assert(rec);
        records.push(rec);
      }
    }
  }
  // 2. Test filtering by each field and combo
  for (const memberId of [member1, member2]) {
    const pageRes = await api.functional.discussionboard.notificationPreferences.index(
      connection,
      {
        body: {
          discussionboard_member_id: memberId,
          page: 1,
          limit: 100,
        } satisfies IDiscussionboardNotificationPreferences.IRequest,
      },
    );
    typia.assert(pageRes);
    for (const rec of pageRes.data) {
      TestValidator.equals("member filter")(rec.discussionboard_member_id)(memberId);
    }
  }
  for (const code of codes) {
    const pageRes = await api.functional.discussionboard.notificationPreferences.index(
      connection,
      {
        body: {
          code,
          page: 1,
          limit: 100,
        } satisfies IDiscussionboardNotificationPreferences.IRequest,
      },
    );
    typia.assert(pageRes);
    for (const rec of pageRes.data) {
      TestValidator.equals("code filter")(rec.code)(code);
    }
  }
  const combos = [
    { email_enabled: true },
    { inapp_enabled: true },
    { browser_enabled: true },
  ];
  for (const combo of combos) {
    const pageRes = await api.functional.discussionboard.notificationPreferences.index(
      connection,
      {
        body: {
          ...combo,
          page: 1,
          limit: 100,
        } satisfies IDiscussionboardNotificationPreferences.IRequest,
      },
    );
    typia.assert(pageRes);
    for (const rec of pageRes.data) {
      for (const [k, v] of Object.entries(combo)) {
        TestValidator.equals(`filter ${k}`)(rec[k as keyof typeof rec])(v);
      }
    }
  }
  // 3. Pagination tests: Sorted deterministic by id for test repeatability
  const allPage = await api.functional.discussionboard.notificationPreferences.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IDiscussionboardNotificationPreferences.IRequest,
    },
  );
  typia.assert(allPage);
  const sorted = [...allPage.data].sort((a, b) => a.id.localeCompare(b.id));
  {
    const page1 = await api.functional.discussionboard.notificationPreferences.index(
      connection,
      {
        body: { page: 1, limit: 2 } satisfies IDiscussionboardNotificationPreferences.IRequest,
      },
    );
    typia.assert(page1);
    TestValidator.equals("page size")(page1.data.length)(2);
    TestValidator.equals("pagination meta")(page1.pagination.current)(1);
    TestValidator.equals("pagination meta")(page1.pagination.limit)(2);
    // verify correct slice by id
    TestValidator.equals("first two ids")(
      page1.data.map((x) => x.id),
    )(
      sorted.slice(0, 2).map((x) => x.id),
    );
  }
  {
    const page2 = await api.functional.discussionboard.notificationPreferences.index(
      connection,
      {
        body: { page: 2, limit: 2 } satisfies IDiscussionboardNotificationPreferences.IRequest,
      },
    );
    typia.assert(page2);
    TestValidator.equals("page size")(page2.data.length)(2);
    TestValidator.equals("pagination meta")(page2.pagination.current)(2);
    TestValidator.equals("next two ids")(
      page2.data.map((x) => x.id),
    )(
      sorted.slice(2, 4).map((x) => x.id),
    );
  }
}

