/**
 * Test updating notification channel preferences for an existing record.
 *
 * This test ensures that an existing notification preference can be updated for channel flags.
 *
 * Business context:
 * - Each member can control which notification channels (email, in-app, browser) they wish to receive for a given template/event code (e.g., reply notification).
 * - Regulatory and privacy compliance mandates that opt-in/out for each channel is strictly respected, and any updates are audit-trailed by updated_at timestamps.
 *
 * Test Steps:
 * 1. Create a notification preference for a member (with explicit initial flags)
 * 2. Update one or more channel flags (email_enabled, inapp_enabled, browser_enabled) via PUT, by id
 * 3. Verify the response:
 *    - id, member id, and notification code remain unchanged
 *    - The updated channel flags reflect the new values
 *    - updated_at is advanced from the initial record
 * 4. (GET endpoint for notification preference by id is not provided, so retrieval validation is omitted)
 */
export async function test_api_discussionboard_notificationPreferences_test_update_notification_preference_channels_success(
  connection: api.IConnection,
) {
  // 1. Create a notification preference for a user and a specific template code
  const createInput: IDiscussionboardNotificationPreferences.ICreate = {
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    code: "reply",
    email_enabled: true,
    inapp_enabled: false,
    browser_enabled: false,
  };
  const initialPref = await api.functional.discussionboard.notificationPreferences.create(
    connection,
    { body: createInput },
  );
  typia.assert(initialPref);

  // 2. Update the notification channel flags for that record via PUT
  const updatedInput: IDiscussionboardNotificationPreferences.IUpdate = {
    code: initialPref.code, // code unchanged
    email_enabled: false, // set to new state
    inapp_enabled: true,  // set to new state
    browser_enabled: initialPref.browser_enabled, // leave unchanged
  };
  const updatedPref = await api.functional.discussionboard.notificationPreferences.update(
    connection,
    {
      id: initialPref.id,
      body: updatedInput,
    },
  );
  typia.assert(updatedPref);

  // 3. Verify response reflects the new preferences and updated_at advances
  TestValidator.equals("id remains the same")(updatedPref.id)(initialPref.id);
  TestValidator.equals("discussionboard_member_id remains")(updatedPref.discussionboard_member_id)(initialPref.discussionboard_member_id);
  TestValidator.equals("code remains")(updatedPref.code)(initialPref.code);
  TestValidator.equals("email_enabled updated")(updatedPref.email_enabled)(false);
  TestValidator.equals("inapp_enabled updated")(updatedPref.inapp_enabled)(true);
  TestValidator.equals("browser_enabled unchanged")(updatedPref.browser_enabled)(initialPref.browser_enabled);
  TestValidator.notEquals("updated_at advanced")(updatedPref.updated_at)(initialPref.updated_at);

  // 4. GET confirm step skipped — GET endpoint for specific id is not available.
}

