 *
 * Steps:
 * 1. Create a new comment report with initial values
 * 2. Update one or more of: reason, discussionboard_member_id, or discussionboard_report_type_id using PUT
 * 3. Assert that the response keeps the same id, the mutable fields are updated, and the unchanged fields remain as before (if not provided in the update body)
 */
export async function test_api_discussionboard_test_update_comment_report_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a new comment report
  const initialReport = await api.functional.discussionboard.commentReports.create(connection, {
    body: {
      discussionboard_comment_id: typia.random<string & tags.Format<"uuid">>(),
      discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
