 * 1. 유효한 comment report를 생성한다(정상 ID 사용)
 * 2. 무작위/비존재 UUID를 comment id로 지정하여 update API를 호출한다
 * 3. update 실패(무결성 위반 또는 not found 에러)인지 TestValidator.error로 검증한다
 */
export async function test_api_discussionboard_commentReports_test_update_comment_report_to_invalid_comment_id(
  connection: api.IConnection,
) {
  // 1. 유효한 comment report 생성
  const validReport: Idiscussionboard_comment_reports =
    await api.functional.discussionboard.commentReports.create(connection, {
      body: {
