/**
 * Test the retrieval of a single notification template by valid ID.
 *
 * This test validates the GET /discussionboard/notificationTemplates/{id} endpoint
 * by following a complete workflow: it first creates a notification template, then retrieves it
 * using the returned ID, and asserts that all schema properties are present and accurately reflect
 * the values initially set during creation. This ensures the retrieval API is functioning as intended
 * and that data integrity is preserved.
 *
 * Steps:
 * 1. Create a notification template using the POST endpoint
 * 2. Retrieve the notification template by its ID using the GET endpoint
 * 3. Assert that all persisted fields (code, name, description, subject, body, is_active) match
 *    between creation and retrieval
 * 4. Confirm the id and timestamps are correctly preserved and formatted
 * 5. Verify response strictly matches INotificationTemplate type
 */
export async function test_api_discussionboard_notificationTemplates_test_get_notification_template_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a notification template
  const input: INotificationTemplate.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(1),
    subject: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_active: true,
  };
  const created: INotificationTemplate = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    { body: input },
  );
  typia.assert(created);

  // 2. Retrieve the template by its ID
  const retrieved: INotificationTemplate = await api.functional.discussionboard.notificationTemplates.at(
    connection,
    { id: created.id },
  );
  typia.assert(retrieved);

  // 3. Assert persisted field values between creation and retrieval
  //    Ensure all user-settable properties match exactly
  TestValidator.equals("code should match")(retrieved.code)(created.code);
  TestValidator.equals("name should match")(retrieved.name)(created.name);
  TestValidator.equals("description should match")(
    retrieved.description
  )(created.description);
  TestValidator.equals("subject should match")(retrieved.subject)(created.subject);
  TestValidator.equals("body should match")(retrieved.body)(created.body);
  TestValidator.equals("is_active should match")(retrieved.is_active)(created.is_active);

  // 4. Confirm template id and timestamps
  TestValidator.equals("id must remain stable")(retrieved.id)(created.id);
  TestValidator.predicate("created_at is ISO date-time")(
    !!retrieved.created_at && !Number.isNaN(Date.parse(retrieved.created_at))
  );
  TestValidator.predicate("updated_at is ISO date-time")(
    !!retrieved.updated_at && !Number.isNaN(Date.parse(retrieved.updated_at))
  );

  // 5. Schema compliance assertion for retrieval result
  typia.assert<INotificationTemplate>(retrieved);
}

