 * notification template 업데이트 시 extraneous field(스키마에 없는 필드) 또는 잘못된 타입이 포함된 경우 API가 올바르게 validation 에러를 반환하는지 검증합니다.
 *
 * 이 테스트는 다음을 검증합니다:
 * - 올바른 notification template이 선행 생성되는지
 * - extraneous fields(스키마에 없는 필드 포함)로 update 시도 시 validation 에러가 발생하는지
 * - 올바르지 않은 타입(예: string 대신 number, boolean 대신 string 등)으로 update 시도 시 validation 에러가 발생하는지
 *
 * 테스트 절차:
 * 1. 올바른 notification template 생성 (의존 엔드포인트 활용)
 * 2. extraneous fields 포함 update 시 validation 에러 발생 검증
 * 3. 잘못된 타입 포함 update 시 validation 에러 발생 검증
 */
export async function test_api_discussionboard_notificationTemplates_test_update_notification_template_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. 올바른 notification template 생성
  const createBody: INotificationTemplate.ICreate = {
    code: RandomGenerator.alphabets(8),
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
    subject: RandomGenerator.paragraph()(),
    body: RandomGenerator.paragraph()(),
    is_active: true,
  };
  const template = await api.functional.discussionboard.notificationTemplates.create(
    connection,
    { body: createBody },
  );
  typia.assert(template);

  // 2. extraneous fields 포함 update 시도 (유효하지 않은 필드 포함)
  await TestValidator.error("extraneous 필드 포함시 validation 에러")(
    async () => {
      await api.functional.discussionboard.notificationTemplates.update(
        connection,
        {
          id: template.id,
          body: {
            name: RandomGenerator.alphabets(15),
            extraneousField: "not allowed", // 스키마에 없는 필드
          } as any, // 타입 위반 intentional
        },
      );
    },
  );

  // 3. 잘못된 타입이 포함된 update 시도
  await TestValidator.error("타입이 잘못된 값이 포함될 때 validation 에러")(
    async () => {
      await api.functional.discussionboard.notificationTemplates.update(
        connection,
        {
          id: template.id,
          body: {
            is_active: "not_boolean", // boolean 대신 string
            code: 987654, // string 대신 number
          } as any,
        },
      );
    },
  );
}

