import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IAdminAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAssignment";

/**
 * Validate successful creation of an admin assignment in the discussion board system.
 *
 * This test covers a realistic workflow in which an existing member is promoted to admin by an already privileged admin user. The process ensures that both the assignee (target member) and assigning admin are registered members, and that the assignment is immediately active (no revoked_at).
 *
 * Steps:
 * 1. Register a regular member who will receive admin privileges (target member).
 * 2. Register an admin user who will perform the assignment.
 * 3. Call the admin assignment endpoint with member_id set to the regular member's id, assigned_by_admin_id set to the admin member's id, assigned_at set to a valid current timestamp, and omit revoked_at.
 * 4. Validate the response: ensure all assignment fields exist, value constraints are met, and the admin assignment is active (revoked_at null or undefined).
 * 5. Ensure no more than one admin assignment is created for the member within the scope of this transaction.
 */
export async function test_api_discussionboard_admins_test_create_admin_assignment_with_valid_member_and_admin(connection: api.IConnection) {
  // 1. Register a regular user (target of assignment)
  const targetMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const targetMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: targetMemberInput });
  typia.assert(targetMember);
  TestValidator.equals("member role assignment target is correct")(targetMember.role)("member");
  TestValidator.equals("member is active")(targetMember.is_active)(true);

  // 2. Register an admin user (the assignee - must be role: 'admin')
  const adminMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphaNumeric(10),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "admin",
    is_active: true,
  };
  const adminMember: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, { body: adminMemberInput });
  typia.assert(adminMember);
  TestValidator.equals("admin role assignment user is correct")(adminMember.role)("admin");
  TestValidator.equals("admin user is active")(adminMember.is_active)(true);

  // 3. Call admin assignment creation endpoint
  const now = new Date().toISOString();
  const adminAssignmentInput: IAdminAssignment.ICreate = {
    member_id: targetMember.id,
    assigned_by_admin_id: adminMember.id,
    assigned_at: now,
    // omit revoked_at on purpose for immediate (active) assignment
  };
  const assignment: IAdminAssignment = await api.functional.discussionboard.admins.create(connection, { body: adminAssignmentInput });
  typia.assert(assignment);

  // 4. Validate returned assignment object and fields
  TestValidator.equals("assignment member_id")(assignment.member_id)(targetMember.id);
  TestValidator.equals("assigned_by_admin_id matches admin")(assignment.assigned_by_admin_id)(adminMember.id);
  TestValidator.equals("assigned_at matches")(assignment.assigned_at)(now);
  TestValidator.equals("assignment is active (revoked_at is null or undefined)")(assignment.revoked_at ?? null)(null);
  TestValidator.equals("required assignment fields exist")(Object.keys(assignment).sort())(["id","member_id","assigned_by_admin_id","assigned_at","revoked_at"].sort());
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IAdminAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAssignment";

/**
 * Validates uniqueness constraint for admin assignment creation.
 *
 * This test checks that a member cannot be assigned admin rights more than once.
 * The endpoint must enforce a unique constraint so there cannot be two admin assignments for the same member.
 *
 * Workflow steps:
 * 1. Create two members via the /discussionboard/members endpoint: one (admin) who will do the assigning, and one (target) to be assigned admin rights.
 * 2. Assign admin role to the target member using /discussionboard/admins, acting as the admin.
 * 3. Attempt to assign admin again to the same member (with the same member_id, assigned_by_admin_id, and new assigned_at timestamp).
 * 4. The second assignment attempt must fail with a constraint/uniqueness error (duplicate assignment).
 *     - This confirms that only a single admin assignment per member is permitted.
 * 5. (Extra validation): The test should validate that the first admin assignment record is returned correctly and matches expectations.
 */
export async function test_api_discussionboard_test_create_admin_assignment_duplicate_for_same_member(
  connection: api.IConnection,
) {
  // 1. Create the target member
  const targetMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "member",
    is_active: true,
  };
  const targetMember = await api.functional.discussionboard.members.create(connection, { body: targetMemberInput });
  typia.assert(targetMember);

  // 2. Create an admin member to perform assignment
  const adminMemberInput: IDiscussionboardMember.ICreate = {
    username: RandomGenerator.alphabets(8),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    role: "admin",
    is_active: true,
  };
  const adminMember = await api.functional.discussionboard.members.create(connection, { body: adminMemberInput });
  typia.assert(adminMember);

  // 3. Assign admin privileges to the target member (first time - should succeed)
  const now = new Date().toISOString();
  const assignmentInput: IAdminAssignment.ICreate = {
    member_id: targetMember.id,
    assigned_by_admin_id: adminMember.id,
    assigned_at: now,
    revoked_at: null,
  };
  const assignment = await api.functional.discussionboard.admins.create(connection, { body: assignmentInput });
  typia.assert(assignment);
  TestValidator.equals("assignment member_id matches")(assignment.member_id)(targetMember.id);
  TestValidator.equals("assignment assigned_by_admin_id matches")(assignment.assigned_by_admin_id)(adminMember.id);
  TestValidator.equals("assignment assigned_at matches")(assignment.assigned_at)(now);
  TestValidator.equals("assignment revoked_at is null")(assignment.revoked_at)(null);

  // 4. Attempt to assign admin again to the same member (should fail with uniqueness error)
  const secondAssignmentInput: IAdminAssignment.ICreate = {
    ...assignmentInput,
    assigned_at: new Date(Date.now() + 1000).toISOString(), // new timestamp
  };
  await TestValidator.error("duplicate admin assignment should fail")(() =>
    api.functional.discussionboard.admins.create(connection, { body: secondAssignmentInput })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMember";
import type { IAdminAssignment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAdminAssignment";

/**
 * Test the full admin assignment revoke and restore lifecycle with /discussionboard/admins/{id} (PUT).
 *
 * 1. Create the user who will become the admin target member.
 * 2. Create the admin who assigns admin privileges.
 * 3. Assign admin privilege from the admin to the member (should be active/no revoked_at).
 * 4. Update the admin assignment and set revoked_at to now (revoke privileges).
 * 5. Assert that revoked_at is set and assignment is effectively inactive.
 * 6. Update again - set revoked_at to null (restore privileges).
 * 7. Assert that revoked_at is null and assignment is active again.
 */
export async function test_api_discussionboard_test_update_admin_assignment_revoke_and_reassign(
  connection: api.IConnection,
) {
  // 1. Create member (target for admin assignment)
  const member: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "member",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(member);

  // 2. Create admin (who assigns the privilege)
  const assigner: IDiscussionboardMember = await api.functional.discussionboard.members.create(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(10),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      role: "admin",
      is_active: true,
    } satisfies IDiscussionboardMember.ICreate,
  });
  typia.assert(assigner);

  // 3. Assign admin privilege (active, no revoked_at)
  const now = new Date().toISOString();
  const adminAssignment = await api.functional.discussionboard.admins.create(connection, {
    body: {
      member_id: member.id,
      assigned_by_admin_id: assigner.id,
      assigned_at: now,
      revoked_at: null,
    } satisfies IAdminAssignment.ICreate,
  });
  typia.assert(adminAssignment);
  TestValidator.equals("initial assignment active")(adminAssignment.revoked_at)(null);

  // 4. Update to set revoked_at (revoke privileges)
  const revokeTime = new Date(Date.now() + 1000).toISOString();
  const revoked = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: revokeTime,
    } satisfies IAdminAssignment.IUpdate,
  });
  typia.assert(revoked);
  TestValidator.equals("assignment revoked")(revoked.revoked_at)(revokeTime);

  // 5. Update again - set revoked_at to null (restore privileges)
  const restored = await api.functional.discussionboard.admins.update(connection, {
    id: adminAssignment.id,
    body: {
      revoked_at: null,
    } satisfies IAdminAssignment.IUpdate,
  });
  typia.assert(restored);
  TestValidator.equals("assignment restored active")(restored.revoked_at)(null);
}

