  const stillChannel2 = await api.functional.discussionboard.channels.update(connection, {
    id: channel2.id,
    body: {
      code: code2,
      name: channel2.name,
      description: channel2.description,
      position: channel2.position,
      active: channel2.active,
    } satisfies IDiscussionboardChannel.IUpdate,
  });
