import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardChannel";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Validate deletion blocking by foreign key constraints for discussionboard channels.
 *
 * This test ensures that attempting to delete a channel which is still referenced
 * by a section (via foreign key) fails as expected, preserving referential integrity.
 *
 * Steps:
 * 1. Create a channel.
 * 2. Create a section referencing that channel.
 * 3. Attempt to delete the channel, expecting the API to throw a constraint violation error.
 *  
 * This confirms the API protects against orphaned section records and informs
 * users that the channel cannot be removed before all dependent data (sections, etc.) is unlinked first.
 */
export async function test_api_discussionboard_test_delete_channel_with_foreign_key_constraints(
  connection: api.IConnection,
) {
  // 1. Create a new discussionboard channel
  const channelInput = {
    code: RandomGenerator.alphaNumeric(6),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(1),
    position: 1,
    active: true,
  } satisfies IDiscussionboardChannel.ICreate;
  const channel = await api.functional.discussionboard.channels.create(connection, { body: channelInput });
  typia.assert(channel);

  // 2. Create a section referencing the above channel
  const sectionInput = {
    discussionboard_channel_id: channel.id,
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.content()()(1),
    position: 1,
    active: true,
  } satisfies IDiscussionboardSection.ICreate;
  const section = await api.functional.discussionboard.sections.create(connection, { body: sectionInput });
  typia.assert(section);

  // 3. Attempt to delete the channel — expect error due to FK constraint
  await TestValidator.error("delete channel fails due to FK section reference")(async () => {
    await api.functional.discussionboard.channels.erase(connection, {
      id: channel.id,
    });
  });
}
